contracts/bridge/BridgeDex.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/utils/cryptography/MessageHashUtils.sol";
import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

struct ProviderTicket {
    uint256 amount;
    uint256 chainBId;
    uint256 requestId;
    uint256 deadline;
    bytes signature;
    address bridger;
}

struct Lock {
    uint256 amount;
    uint256 accepted;
    uint256 nonce;
    uint256[] acceptedChains;
    ProviderTicket[] tickets;
    address token;
    address owner;
    uint16 fees;
}

struct Request {
    uint256 amount;
    uint256 chainAId;
    uint256 lockId;
    uint256 requestId;
    address tokenBContract;
    address sender;
    address provider;
    uint64 deadline;
}

/// @title A simple Decentralized bridge
contract BridgeDex is Ownable {
    uint256 public lockNonce;
    uint256 public bridgeNonce;
    uint256 public protocolFees = 10;

    mapping(uint256 => Lock) public idToLock;
    mapping(address => uint256[]) public tokenContractToRequestIds;
    mapping(address => uint256[]) public tokenContractToLockIds;
    mapping(uint256 => Request) public idToRequest;

    mapping(address => uint256[]) public myRequests;
    mapping(address => uint256[]) public myLocks;

    event LockCreated(
        uint256 indexed id,
        address indexed bridger,
        uint256 amount,
        address tokenAContract,
        uint64 date
    );
    event RequestPublished(
        address indexed _bridger,
        uint256 _amount,
        uint256 _chainAId,
        uint256 _lockId,
        uint256 _requestId,
        address _tokenBContract,
        uint256 _deadline
    );

    event NewTicket(
        uint256 _amount,
        uint256 _deadline,
        uint256 _chainBId,
        uint256 _lockId,
        uint256 _requestId,
        address _bridger
    );

    event NewWithdraw(
        uint256 _lockId,
        uint256 _challengeIndex,
        uint256 _chainBId,
        uint256 _requestId,
        bytes _signature
    );

    constructor() Ownable(msg.sender) {}

    /**
     * @notice Used to lock a certain amount of a certain token to allow bridge operations
     *
     * @param _amount - The amount to lock into the contract
     * @param _acceptedChains - The chainids where the provider accepts his funds to be bridged
     * @param _tokenAContract - The ERC20 token address to lock
     * @param _fees - Fees the provider is going to take (on a /10000 basis)
     */
    function lock(
        uint256 _amount,
        address _tokenAContract,
        uint256[] calldata _acceptedChains,
        uint256 _fees
    ) external {
        uint256 lockId = ++lockNonce;

        Lock storage l = idToLock[lockId];
        myLocks[msg.sender].push(lockId);
        tokenContractToLockIds[_tokenAContract].push(lockId);

        ERC20 c = ERC20(_tokenAContract);

        l.token = _tokenAContract;
        l.owner = msg.sender;
        l.amount = _amount;
        l.nonce = lockId;
        l.acceptedChains = _acceptedChains;
        l.fees = uint16(_fees);
        c.transferFrom(msg.sender, address(this), _amount);

        emit LockCreated(
            lockId,
            msg.sender,
            _amount,
            _tokenAContract,
            uint64(block.timestamp)
        );
    }

    /**
     * @notice Used to publish a bridge request on chainB
     *
     * @param _amount - The total amount of token to bridge
     * @param _chainAId - The id of the chain where the bridger will provide tokens
     * @param _lockId - The nonce of the lock on the chain A
     * @param _deadline - The deadline corresponding to the chain A lock
     * @param _tokenBContract - The address of the token willing to be exchanged on chain B
     * @param _provider - The chosen provider on chainA
     */
    function publishRequest(
        uint256 _amount,
        uint256 _chainAId,
        uint256 _lockId,
        uint256 _deadline,
        address _tokenBContract,
        address _provider
    ) external {
        uint256 _requestId = ++bridgeNonce;

        tokenContractToRequestIds[_tokenBContract].push(_requestId);
        myRequests[msg.sender].push(_requestId);

        Request storage request = idToRequest[_requestId];
        request.amount = _amount;
        request.chainAId = _chainAId;
        request.lockId = _lockId;
        request.requestId = _requestId;
        request.tokenBContract = _tokenBContract;
        request.sender = msg.sender;
        request.provider = _provider;
        request.deadline = uint64(_deadline);

        ERC20(_tokenBContract).transferFrom(msg.sender, address(this), _amount);

        emit RequestPublished(
            msg.sender,
            _amount,
            _chainAId,
            _lockId,
            _requestId,
            _tokenBContract,
            _deadline
        );
    }

    /**
     * @notice - Used by the provider to give a ticket to the trusted bridger
     * @param _lockId - The lock for the given transaction
     * @param _bridger - The bridger of the chainB
     *
     */
    function acceptBridger(
        uint256 _amount,
        uint256 _lockId,
        uint256 _chainBId,
        uint256 _deadline,
        uint256 _requestId,
        address _bridger
    ) external {
        Lock storage l = idToLock[_lockId];

        require(l.owner == msg.sender, "You are not the owner of the lock");
        require(l.amount - l.accepted >= _amount, "Not enough on the lock");

        bytes memory challengerSignature;
        l.tickets.push(
            ProviderTicket({
                amount: _amount,
                chainBId: _chainBId,
                requestId: _requestId,
                deadline: _deadline,
                bridger: _bridger,
                signature: challengerSignature
            })
        );

        l.accepted += _amount;

        emit NewTicket(
            _amount,
            _deadline,
            _chainBId,
            _lockId,
            _requestId,
            _bridger
        );
    }

    /**
     * @notice Used by the bridger to withdraw its funds on the chain A
     *
     * @param _bridgerSignature - The signature of the bridger allowing the provider to withdraw its funds on chain B
     * @param _ticketIndex - The index of the ticket in the ticket queue
     * @param _lockId - The id of the lock to withdraw from
     */
    function bridgerWithdraw(
        bytes calldata _bridgerSignature,
        uint256 _ticketIndex,
        uint256 _lockId
    ) external {
        Lock storage l = idToLock[_lockId];
        ProviderTicket storage ticket = l.tickets[_ticketIndex];

        require(ticket.deadline > block.timestamp);
        require(msg.sender == ticket.bridger);
        require(ticket.amount > 0);

        _verify(
            ticket.bridger,
            _bridgerSignature,
            abi.encodePacked(ticket.chainBId, ticket.requestId)
        );

        uint256 providerFee = (ticket.amount * l.fees) / 1e4;
        uint256 prtlFee = (protocolFees * providerFee) / 100;
        uint256 amount = ticket.amount - providerFee;

        l.amount -= amount + prtlFee;
        l.accepted -= ticket.amount;
        ticket.amount = 0;
        ticket.signature = _bridgerSignature;

        ERC20(l.token).transfer(msg.sender, amount);
        ERC20(l.token).transfer(owner(), prtlFee);

        emit NewWithdraw(
            _lockId,
            _ticketIndex,
            ticket.chainBId,
            ticket.requestId,
            _bridgerSignature
        );
    }

    /**
     * @notice Used on chain B to withdraw the funds of the bridger by the provider
     * Anyone can send this signature as the only receiver of the lock is the chainA
     * provider
     *
     * @param _bridgerSignature - The signature sent on the chain A by the bridger to redeem the funds
     * @param _requestId - The id of the request we are going to withdraw from
     */
    function withdrawRequest(
        bytes calldata _bridgerSignature,
        uint256 _requestId
    ) external {
        (address token, address provider, uint256 amount) = _deleteRequest(
            _bridgerSignature,
            _requestId
        );
        ERC20(token).transfer(provider, amount);
    }

    /**
     * @notice Used on chain B to relock the funds of the bridger into a provider lock
     *
     * @param _bridgerSignature - The signature sent on the chain A by the bridger to redeem the funds
     * @param _requestId - The id of the request we are going to withdraw from
     * @param _lockId - The id of the lock to relock into
     */
    function relockRequest(
        bytes calldata _bridgerSignature,
        uint256 _requestId,
        uint256 _lockId
    ) external {
        (address token, address provider, uint256 amount) = _deleteRequest(
            _bridgerSignature,
            _requestId
        );

        Lock storage l = idToLock[_lockId];

        require(l.owner == provider);
        require(l.owner == msg.sender);
        require(l.token == token);
        l.amount += amount;
    }

    /**
     * @notice - Used by the lock owner to delete an outdated ticket in order
     * to get the accepted amount of the lock released
     *
     * @param _lockId - The id of the lock to remove the ticket from
     * @param _ticketIndex - The index of the ticket to remove
     */
    function deleteTicket(uint256 _lockId, uint256 _ticketIndex) external {
        Lock storage l = idToLock[_lockId];
        ProviderTicket storage ticket = l.tickets[_ticketIndex];

        require(l.owner == msg.sender);
        require(ticket.deadline < block.timestamp);

        l.accepted -= ticket.amount;

        if (_ticketIndex == l.tickets.length - 1) {
            l.tickets.pop();
        } else {
            l.tickets[_ticketIndex] = l.tickets[l.tickets.length - 1];
            l.tickets.pop();
        }
    }

    /**
     * @notice Used to withdraw the locked funds, funds can be withdraw immediatly if there is no active challenger
     * @param _lockId - The lock id on the chain A
     */
    function withdrawLock(uint256 _lockId) external {
        Lock storage l = idToLock[_lockId];

        require(l.owner == msg.sender);
        uint256 i;

        for (i = 0; i < l.tickets.length; ++i) {
            require(
                l.tickets[i].deadline < block.timestamp ||
                    l.tickets[i].amount == 0
            );
        }

        uint256 amount = l.amount;
        address token = l.token;

        for (i = 0; i < myLocks[msg.sender].length; ++i) {
            if (myLocks[msg.sender][i] == _lockId) {
                _splice(myLocks[msg.sender], i);
                break;
            }
        }

        for (i = 0; i < tokenContractToLockIds[l.token].length; ++i) {
            if (tokenContractToLockIds[l.token][i] == _lockId) {
                _splice(tokenContractToLockIds[l.token], i);
                break;
            }
        }
        delete idToLock[_lockId];

        ERC20(token).transfer(msg.sender, amount);
    }

    /**
     * @notice - Used to withdraw the funds locked for a particular token request
     * @param _requestId - The id of the challenge to withdraw the funds from
     */
    function withdrawChainBRequest(uint256 _requestId) external {
        Request storage request = idToRequest[_requestId];

        require(request.sender == msg.sender);
        require(request.deadline < block.timestamp);

        uint256 amount = request.amount;
        address token = request.tokenBContract;

        for (uint256 i = 0; i < myRequests[msg.sender].length; ++i) {
            if (myRequests[msg.sender][i] == _requestId) {
                _splice(myRequests[msg.sender], i);
                break;
            }
        }
        for (
            uint256 i = 0;
            i < tokenContractToRequestIds[request.tokenBContract].length;
            ++i
        ) {
            if (
                tokenContractToRequestIds[request.tokenBContract][i] ==
                _requestId
            ) {
                _splice(tokenContractToRequestIds[request.tokenBContract], i);
                break;
            }
        }
        delete idToRequest[_requestId];

        ERC20(token).transfer(msg.sender, amount);
    }

    /**
     * @notice Used to extend lock liquidity.
     *
     * @param _lockId - Id of the lock
     * @param _amount - Amount to add
     */
    function addLiquidity(uint256 _lockId, uint256 _amount) external {
        Lock storage l = idToLock[_lockId];
        require(l.owner == msg.sender);

        l.amount += _amount;
        ERC20(l.token).transferFrom(msg.sender, address(this), _amount);
    }

    /**
     * @notice Remove liquidity from a provider lock
     * accepted amount is not withdrawable
     *
     * @param _lockId - Id of the lock
     * @param _amount - Amount to remove
     */
    function removeLiquidity(uint256 _lockId, uint256 _amount) external {
        Lock storage l = idToLock[_lockId];

        require(l.owner == msg.sender);
        require(l.amount - l.accepted >= _amount);
        l.amount -= _amount;

        ERC20(l.token).transfer(msg.sender, _amount);

        if (l.amount == 0) {
            for (uint256 i = 0; i < myLocks[msg.sender].length; ++i) {
                if (myLocks[msg.sender][i] == _lockId) {
                    _splice(myLocks[msg.sender], i);
                    break;
                }
            }
            for (
                uint256 i = 0;
                i < tokenContractToLockIds[l.token].length;
                ++i
            ) {
                if (tokenContractToLockIds[l.token][i] == _lockId) {
                    _splice(tokenContractToLockIds[l.token], i);
                    break;
                }
            }
            delete idToLock[_lockId];
        }
    }

    /**
     * @notice Updated the protocol fees
     * @param _newFee - % of new fee
     */
    function changeProtocolFees(uint256 _newFee) external onlyOwner {
        require(_newFee < 100);
        protocolFees = _newFee;
    }

    /**
     * @notice - Used to get acces to all the address' locks at once
     * @param _owner - The address to retrieve the locks from
     * @return uint256[] - An array containing the address active lock ids
     */
    function getMyLocks(address _owner) external view returns (Lock[] memory) {
        uint256[] memory lockIds = myLocks[_owner];
        Lock[] memory response = new Lock[](lockIds.length);

        for (uint256 i; i < lockIds.length; ++i) {
            response[i] = idToLock[lockIds[i]];
        }
        return response;
    }

    /**
     * @notice - Used to get the tickets of a given lock, not possible other way
     * @param _lockId - The id of the lock to get the challenges
     * @return - The array of the challenges for the given lock
     */
    function getLockTickets(
        uint256 _lockId
    ) external view returns (ProviderTicket[] memory) {
        return idToLock[_lockId].tickets;
    }

    /**
     * @notice Used to get the active requests for a given address
     * @param _owner - The address to look for request ids
     * @return Requests[] - The list of the active requests for the user
     */
    function getMyRequests(
        address _owner
    ) external view returns (Request[] memory) {
        uint256[] memory requestIds = myRequests[_owner];
        Request[] memory response = new Request[](requestIds.length);

        for (uint256 i; i < requestIds.length; ++i) {
            response[i] = idToRequest[requestIds[i]];
        }
        return response;
    }

    /**
     * @notice - Used to get the list of the request for a given token
     * @param _token - The token address on chain B to look for token requests
     */
    function getRequestsForToken(
        address _token
    ) external view returns (Request[] memory) {
        uint256[] memory requestIds = tokenContractToRequestIds[_token];
        Request[] memory response = new Request[](requestIds.length);

        for (uint256 i; i < requestIds.length; ++i) {
            response[i] = idToRequest[requestIds[i]];
        }
        return response;
    }

    /**
     * @notice - Used to get the list of the locks for a given token
     * @param _token - The token address on chain A to look for token locks
     */
    function getLocksForToken(
        address _token
    ) external view returns (Lock[] memory) {
        uint256[] memory lockIds = tokenContractToLockIds[_token];
        Lock[] memory response = new Lock[](lockIds.length);

        for (uint256 i; i < lockIds.length; ++i) {
            response[i] = idToLock[lockIds[i]];
        }
        return response;
    }

    /**
     * @notice Returns the accepted tickets corresponding to the locks ids given
     * by the user
     *
     * @param _lockIds - The ids of the locks to look into
     * @param _bridger - The address of the bridger to look for
     */
    function getAcceptedTickets(
        uint256[] calldata _lockIds,
        address _bridger
    ) external view returns (ProviderTicket[] memory) {
        uint256 j;
        uint256 id;
        uint256 lastLock;

        ProviderTicket[] memory tickets;
        ProviderTicket[] memory response = new ProviderTicket[](
            _lockIds.length
        );

        for (uint256 i = 0; i < _lockIds.length; ++i) {
            tickets = idToLock[_lockIds[i]].tickets;
            _lockIds[i] == lastLock ? ++j : j = 0;
            lastLock = _lockIds[i];

            for (; j < tickets.length; ++j) {
                if (tickets[j].bridger == _bridger) {
                    response[id++] = tickets[j];
                    break;
                }
            }
        }
        return response;
    }

    function _verify(
        address _address,
        bytes memory _signature,
        bytes memory data
    ) private pure {
        require(
            _address ==
                ECDSA.recover(
                    MessageHashUtils.toEthSignedMessageHash(data),
                    _signature
                ),
            "Invalid signature"
        );
    }

    /**
     * @notice - Used to pop an element from a list (modifies the order of the elements)
     *
     * @param _array - The array from which the element will be deleted
     * @param _index - The index of the element to pop
     */
    function _splice(uint256[] storage _array, uint256 _index) private {
        if (_index == _array.length - 1) {
            _array.pop();
        } else {
            _array[_index] = _array[_array.length - 1];
            _array.pop();
        }
    }

    /**
     * @notice Used to delete a request from the request pool
     *
     * @param _bridgerSignature - The signature sent on the chain A by the bridger to redeem the funds
     * @param _requestId - The id of the request we are going to withdraw from
     */
    function _deleteRequest(
        bytes calldata _bridgerSignature,
        uint256 _requestId
    ) private returns (address, address, uint256) {
        Request memory request = idToRequest[_requestId];

        require(request.deadline > block.timestamp);

        uint256 chainId;
        assembly {
            chainId := chainid()
        }

        _verify(
            request.sender,
            _bridgerSignature,
            abi.encodePacked(chainId, _requestId)
        );

        for (uint256 i = 0; i < myRequests[request.sender].length; ++i) {
            if (myRequests[request.sender][i] == _requestId) {
                _splice(myRequests[request.sender], i);
                break;
            }
        }

        for (
            uint256 i = 0;
            i < tokenContractToRequestIds[request.tokenBContract].length;
            ++i
        ) {
            if (
                tokenContractToRequestIds[request.tokenBContract][i] ==
                _requestId
            ) {
                _splice(tokenContractToRequestIds[request.tokenBContract], i);
                break;
            }
        }

        delete idToRequest[_requestId];
        return (request.tokenBContract, request.provider, request.amount);
    }
}

contracts/bridge/GunL2Bridge.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "../registry/ShogunRelayRegistry.sol";

/**
 * @title GunL2Bridge
 * @notice L2 Bridge contract for Shogun Protocol - Enables trustless deposits and withdrawals
 * @dev Uses Merkle Proofs for verifiable withdrawals from L2 (GunDB) to L1 (Ethereum)
 * 
 * Architecture:
 * - Deposits: Users send ETH to contract, emit Deposit event for GunDB nodes to credit L2 balance
 * - Batch Submission: Registered relays (or dedicated sequencer) submit Merkle Root of current L2 state
 * - Withdrawals: Users provide Merkle Proof to prove their withdrawal is included in the root
 * 
 * Security:
 * - Anti-replay protection via nonce-based leaf hashing
 * - Only registered relays (or dedicated sequencer) can submit batches
 * - Merkle proof verification ensures withdrawals are legitimate
 */
contract GunL2Bridge is Ownable, ReentrancyGuard, Pausable {
    // =========================================== Events ===========================================

    /// @notice Emitted when a user deposits ETH
    /// @param user Address of the depositor
    /// @param amount Amount deposited (in wei)
    /// @param timestamp Block timestamp
    event Deposit(address indexed user, uint256 amount, uint256 timestamp);

    /// @notice Emitted when sequencer submits a new batch (state root)
    /// @param batchId Sequential batch identifier
    /// @param stateRoot Merkle root of the current L2 state
    /// @notice Emitted when sequencer submits a new batch (state root)
    /// @param batchId Sequential batch identifier
    /// @param stateRoot Merkle root of the current L2 state
    event BatchSubmitted(uint256 indexed batchId, bytes32 stateRoot);

    /// @notice Emitted when a user successfully withdraws
    /// @param user Address of the withdrawer
    /// @param amount Amount withdrawn (in wei)
    /// @param nonce Unique nonce for this withdrawal
    event Withdrawal(address indexed user, uint256 amount, uint256 nonce);

    /// @notice Bridge frozen event (censorship proved)
    event BridgeFrozen(bytes32 indexed withdrawalHash, address indexed reporter);

    /// @notice Force withdrawal initiated
    event ForceWithdrawalInitiated(bytes32 indexed withdrawalHash, address indexed user, uint256 amount, uint256 deadline);

    /// @notice Batch finalized after challenge period
    event BatchFinalized(uint256 indexed batchId, bytes32 stateRoot);

    /// @notice Batch challenged and fraud proven
    event BatchChallenged(uint256 indexed batchId, address indexed challenger);
    
    /// @notice Challenger slashed for false challenge
    event ChallengerSlashed(uint256 indexed batchId, address indexed challenger);

    // =========================================== State ===========================================

    /// @notice ShogunRelayRegistry contract address
    ShogunRelayRegistry public relayRegistry;

    /// @notice Optional dedicated sequencer address (if set, only this address can submit batches)
    /// @dev If zero address, any registered relay can submit batches
    address public sequencer;

    /// @notice Current state root (Merkle root of L2 state)
    bytes32 public currentStateRoot;

    /// @notice Current batch ID (increments with each batch submission)
    uint256 public currentBatchId;

    /// @notice Mapping to prevent replay attacks (leaf hash => processed)
    /// @dev Leaf = keccak256(abi.encodePacked(user, amount, nonce))
    mapping(bytes32 => bool) public processedWithdrawals;

    /// @notice Historical batch roots (batchId => stateRoot)
    /// @dev Allows users to withdraw from previous batches even if new ones are submitted
    mapping(uint256 => bytes32) public batchRoots;

    /// @notice Pending force withdrawals (hash => deadline timestamp)
    mapping(bytes32 => uint256) public pendingForceWithdrawals;

    /// @notice Time window for sequencer to include force withdrawal (e.g., 24 hours)
    uint256 public constant FORCE_WITHDRAWAL_WINDOW = 24 hours;

    /// @notice Challenge period before batch is finalized (e.g., 1 day for MVP, 7 days for production)
    uint256 public constant CHALLENGE_PERIOD = 1 days;

    /// @notice Minimum stake required to challenge a batch
    uint256 public constant CHALLENGE_BOND = 0.1 ether;

    /// @notice Batch info for fraud proof tracking
    struct BatchInfo {
        bytes32 root;
        bytes32 dataHash;       // Hash of batch data for re-execution
        uint256 submittedAt;
        bool finalized;
        bool challenged;
        address challenger;
    }

    /// @notice Detailed batch info (for fraud proofs)
    mapping(uint256 => BatchInfo) public batchInfo;

    /// @notice Challenger bonds (batchId => challenger => bond)
    mapping(uint256 => mapping(address => uint256)) public challengerBonds;

    // =========================================== Modifiers ===========================================

    /// @notice Only sequencer or registered relay can submit batches
    modifier onlySequencerOrRelay() {
        // If sequencer is set (non-zero), only sequencer can submit
        if (sequencer != address(0)) {
            require(msg.sender == sequencer, "GunL2Bridge: Not sequencer");
        } else {
            // Otherwise, check if sender is a registered active relay
            require(
                relayRegistry.isActiveRelay(msg.sender),
                "GunL2Bridge: Not sequencer or registered relay"
            );
        }
        _;
    }

    // =========================================== Constructor ===========================================

    /**
     * @notice Initialize the bridge
     * @param _relayRegistry Address of ShogunRelayRegistry contract
     * @param _sequencer Optional dedicated sequencer address (zero address = any relay can submit)
     */
    constructor(address _relayRegistry, address _sequencer) Ownable(msg.sender) {
        require(_relayRegistry != address(0), "GunL2Bridge: Invalid relay registry");
        relayRegistry = ShogunRelayRegistry(_relayRegistry);
        sequencer = _sequencer; // Can be zero address to allow any relay
        currentBatchId = 0;
        // Initial state root is empty (no withdrawals yet)
        currentStateRoot = bytes32(0);
    }

    // =========================================== Deposit (L1 -> L2) ===========================================

    /**
     * @notice Deposit ETH to bridge to L2
     * @dev Emits Deposit event that GunDB nodes listen to for crediting L2 balance
     *      ETH is locked in the contract until withdrawn via Merkle proof
     */
    function deposit() external payable whenNotPaused {
        require(msg.value > 0, "GunL2Bridge: Must send ETH");
        emit Deposit(msg.sender, msg.value, block.timestamp);
    }

    // =========================================== Force Withdrawal (Anti-Censorship) ===========================================

    /**
     * @notice Initiate a force withdrawal request
     * @param amount Amount to withdraw
     * @param nonce Nonce for the withdrawal
     * @dev This starts the timer. If sequencer doesn't include it in a batch within window, bridge can be frozen.
     */
    function initiateForceWithdrawal(uint256 amount, uint256 nonce) external whenNotPaused {
        require(amount > 0, "GunL2Bridge: Invalid amount");
        
        bytes32 leaf = keccak256(abi.encodePacked(msg.sender, amount, nonce));
        require(pendingForceWithdrawals[leaf] == 0, "GunL2Bridge: Already pending");
        require(!processedWithdrawals[leaf], "GunL2Bridge: Already processed");

        uint256 deadline = block.timestamp + FORCE_WITHDRAWAL_WINDOW;
        pendingForceWithdrawals[leaf] = deadline;

        emit ForceWithdrawalInitiated(leaf, msg.sender, amount, deadline);
    }

    /**
     * @notice Prove censorship and freeze the bridge
     * @param user User address
     * @param amount Amount
     * @param nonce Nonce
     * @dev If deadline passed and request still pending, sequencer is censoring.
     */
    function proveCensorship(address user, uint256 amount, uint256 nonce) external {
        bytes32 leaf = keccak256(abi.encodePacked(user, amount, nonce));
        uint256 deadline = pendingForceWithdrawals[leaf];

        require(deadline != 0, "GunL2Bridge: Not pending");
        require(block.timestamp > deadline, "GunL2Bridge: Deadline not passed");

        _pause(); // Freeze the bridge
        emit BridgeFrozen(leaf, msg.sender);
    }

    // =========================================== Batch Submission (Sequencer) ===========================================

    /**
     * @notice Submit a new batch with updated state root
     * @param _newRoot Merkle root of the current L2 state (includes all pending withdrawals)
     * @param _handledForceWithdrawals List of force withdrawal hashes included in this batch
     * @dev Only sequencer (if set) or registered relay can call this. 
     *      MUST acknowledge pending force withdrawals to avoid being accused of censorship.
     */
    function submitBatch(
        bytes32 _newRoot, 
        bytes32[] calldata _handledForceWithdrawals
    ) external onlySequencerOrRelay whenNotPaused {
        require(_newRoot != bytes32(0), "GunL2Bridge: Invalid root");
        
        // Clear handled force withdrawals
        for (uint256 i = 0; i < _handledForceWithdrawals.length; i++) {
            bytes32 leaf = _handledForceWithdrawals[i];
            if (pendingForceWithdrawals[leaf] != 0) {
                delete pendingForceWithdrawals[leaf];
            }
        }

        currentStateRoot = _newRoot;
        currentBatchId++;
        batchRoots[currentBatchId] = _newRoot;
        
        // Store batch info for fraud proof tracking
        batchInfo[currentBatchId] = BatchInfo({
            root: _newRoot,
            dataHash: keccak256(abi.encode(_handledForceWithdrawals)),
            submittedAt: block.timestamp,
            finalized: false,
            challenged: false,
            challenger: address(0)
        });
        
        emit BatchSubmitted(currentBatchId, _newRoot);
    }

    /**
     * @notice Finalize a batch after challenge period
     * @param batchId Batch to finalize
     * @dev Can only be called after CHALLENGE_PERIOD has passed without successful challenge
     */
    function finalizeBatch(uint256 batchId) external {
        BatchInfo storage batch = batchInfo[batchId];
        require(batch.root != bytes32(0), "GunL2Bridge: Invalid batch");
        require(!batch.finalized, "GunL2Bridge: Already finalized");
        require(!batch.challenged, "GunL2Bridge: Batch challenged");
        require(block.timestamp > batch.submittedAt + CHALLENGE_PERIOD, "GunL2Bridge: Challenge period active");
        
        batch.finalized = true;
        emit BatchFinalized(batchId, batch.root);
    }

    /**
     * @notice Challenge a batch (claim fraud)
     * @param batchId Batch to challenge
     * @dev Requires CHALLENGE_BOND stake. If fraud is proven, challenger gets reward.
     */
    function challengeBatch(uint256 batchId) external payable {
        require(msg.value >= CHALLENGE_BOND, "GunL2Bridge: Insufficient bond");
        
        BatchInfo storage batch = batchInfo[batchId];
        require(batch.root != bytes32(0), "GunL2Bridge: Invalid batch");
        require(!batch.finalized, "GunL2Bridge: Already finalized");
        require(!batch.challenged, "GunL2Bridge: Already challenged");
        require(block.timestamp <= batch.submittedAt + CHALLENGE_PERIOD, "GunL2Bridge: Challenge period ended");
        
        batch.challenged = true;
        batch.challenger = msg.sender;
        challengerBonds[batchId][msg.sender] = msg.value;
        
        emit BatchChallenged(batchId, msg.sender);
        
        // In a full implementation, this would trigger dispute resolution
        // For now, we pause the bridge to require manual intervention
        _pause();
    }

    /**
     * @notice Resolve a challenge (owner only for MVP)
     * @param batchId Batch ID
     * @param fraudProven True if fraud was proven, false if challenge was invalid
     */
    function resolveChallenge(uint256 batchId, bool fraudProven) external onlyOwner {
        BatchInfo storage batch = batchInfo[batchId];
        require(batch.challenged, "GunL2Bridge: Not challenged");
        
        address challenger = batch.challenger;
        uint256 bond = challengerBonds[batchId][challenger];
        
        if (fraudProven) {
            // Fraud proven: revert batch, reward challenger
            // Clear the batch root so it cannot be used for withdrawals
            batchRoots[batchId] = bytes32(0);
            batch.root = bytes32(0);
            
            // Return bond to challenger (+ reward from sequencer stake in future)
            (bool sent, ) = payable(challenger).call{value: bond}("");
            require(sent, "GunL2Bridge: Bond return failed");
        } else {
            // False challenge: slash challenger bond
            // Bond goes to sequencer or protocol treasury
            challengerBonds[batchId][challenger] = 0;
            emit ChallengerSlashed(batchId, challenger);
        }
        
        batch.challenged = false;
        _unpause();
    }

    // =========================================== Withdrawal (L2 -> L1) ===========================================

    /**
     * @notice Withdraw ETH from L2 to L1 using Merkle proof
     * @param amount Amount to withdraw (in wei)
     * @param nonce Unique nonce for this withdrawal (prevents replay)
     * @param proof Merkle proof array (sibling hashes from leaf to root)
     * @dev The leaf is computed as keccak256(abi.encodePacked(msg.sender, amount, nonce))
     *      The proof must verify against currentStateRoot
     */
    function withdraw(
        uint256 amount,
        uint256 nonce,
        uint256 batchId,
        bytes32[] calldata proof
    ) external nonReentrant whenNotPaused {
        require(amount > 0, "GunL2Bridge: Invalid amount");
        require(address(this).balance >= amount, "GunL2Bridge: Insufficient contract balance");

        // 1. Compute the leaf hash (user, amount, nonce)
        bytes32 leaf = keccak256(abi.encodePacked(msg.sender, amount, nonce));

        // 2. Check anti-replay: ensure this leaf hasn't been used before
        require(!processedWithdrawals[leaf], "GunL2Bridge: Withdrawal already processed");

        // 3. Verify Merkle proof: leaf must be part of the root for the specified batch
        bytes32 root = batchRoots[batchId];
        require(root != bytes32(0), "GunL2Bridge: Invalid batch ID");
        
        require(
            verifyProof(proof, root, leaf),
            "GunL2Bridge: Invalid Merkle proof"
        );

        // 4. Mark as processed (anti-replay)
        processedWithdrawals[leaf] = true;

        // 5. Transfer ETH to user
        (bool sent, ) = msg.sender.call{value: amount}("");
        require(sent, "GunL2Bridge: ETH transfer failed");

        emit Withdrawal(msg.sender, amount, nonce);
    }

    // =========================================== Merkle Verification ===========================================

    /**
     * @notice Verify a Merkle proof
     * @param proof Array of sibling hashes from leaf to root
     * @param root The Merkle root to verify against
     * @param leaf The leaf hash to verify
     * @return True if proof is valid
     * @dev Uses standard Merkle tree verification (keccak256 pairs, sorted order)
     */
    function verifyProof(
        bytes32[] memory proof,
        bytes32 root,
        bytes32 leaf
    ) internal pure returns (bool) {
        bytes32 computedHash = leaf;

        for (uint256 i = 0; i < proof.length; i++) {
            bytes32 proofElement = proof[i];

            // Sort hashes to ensure deterministic tree structure
            if (computedHash <= proofElement) {
                // Hash(current, sibling)
                computedHash = keccak256(abi.encodePacked(computedHash, proofElement));
            } else {
                // Hash(sibling, current)
                computedHash = keccak256(abi.encodePacked(proofElement, computedHash));
            }
        }

        return computedHash == root;
    }

    // =========================================== Admin Functions ===========================================

    /**
     * @notice Update sequencer address
     * @param _newSequencer New sequencer address (zero address = allow any registered relay)
     * @dev If set to zero address, any registered relay can submit batches.
     *      If set to a specific address, only that address can submit batches.
     */
    function setSequencer(address _newSequencer) external onlyOwner {
        sequencer = _newSequencer; // Can be zero address
    }

    /**
     * @notice Update relay registry address
     * @param _newRelayRegistry New relay registry address
     */
    function setRelayRegistry(address _newRelayRegistry) external onlyOwner {
        require(_newRelayRegistry != address(0), "GunL2Bridge: Invalid relay registry");
        relayRegistry = ShogunRelayRegistry(_newRelayRegistry);
    }

    /**
     * @notice Pause the contract (emergency only)
     */
    function pause() external onlyOwner {
        _pause();
    }

    /**
     * @notice Unpause the contract
     */
    function unpause() external onlyOwner {
        _unpause();
    }

    /**
     * @notice Emergency withdraw stuck ETH (owner only)
     * @param amount Amount to withdraw
     * @param to Recipient address
     */
    function emergencyWithdraw(uint256 amount, address payable to) external onlyOwner {
        require(to != address(0), "GunL2Bridge: Invalid recipient");
        require(address(this).balance >= amount, "GunL2Bridge: Insufficient balance");
        (bool sent, ) = to.call{value: amount}("");
        require(sent, "GunL2Bridge: ETH transfer failed");
    }

    // =========================================== View Functions ===========================================

    /**
     * @notice Check if a withdrawal has been processed (anti-replay check)
     * @param user User address
     * @param amount Withdrawal amount
     * @param nonce Withdrawal nonce
     * @return True if already processed
     */
    function isWithdrawalProcessed(
        address user,
        uint256 amount,
        uint256 nonce
    ) external view returns (bool) {
        bytes32 leaf = keccak256(abi.encodePacked(user, amount, nonce));
        return processedWithdrawals[leaf];
    }

    /**
     * @notice Get contract ETH balance
     * @return Balance in wei
     */
    function getBalance() external view returns (uint256) {
        return address(this).balance;
    }

    /**
     * @notice Receive ETH (for deposits)
     * @dev Respects pause state to prevent deposits during emergencies
     */
    receive() external payable whenNotPaused {
        if (msg.value > 0) {
            emit Deposit(msg.sender, msg.value, block.timestamp);
        }
    }
}

contracts/datasale/DataPostRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/**
 * @title DataPostRegistry
 * @notice Registry for data posts (similar to Erasure Posts)
 * @dev Allows users to publish available data for sale
 * 
 * Features:
 * - Publish data posts with proofhash
 * - Search/discover available data
 * - Track seller reputation
 */
contract DataPostRegistry is Ownable, Pausable {
    // =========================================== Types ===========================================

    /// @notice Data post information
    struct DataPost {
        bytes32 postId;              // Unique post identifier
        address seller;              // Seller address
        bytes32 proofHash;           // SHA256 hash of raw data (proof of existence)
        string encryptedDataHash;    // IPFS CID of encrypted data
        string description;          // Description of data
        string category;             // Category/tag for search
        uint256 priceUSDC;          // Price in USDC (6 decimals)
        uint256 createdAt;          // Creation timestamp
        bool active;                // Whether post is active
    }

    // =========================================== State ===========================================

    /// @notice Data posts by ID
    mapping(bytes32 => DataPost) public posts;

    /// @notice Posts by seller
    mapping(address => bytes32[]) public postsBySeller;

    /// @notice Posts by category (for discovery)
    mapping(string => bytes32[]) public postsByCategory;

    /// @notice All active post IDs (for discovery)
    bytes32[] public activePosts;

    /// @notice Index in activePosts array
    mapping(bytes32 => uint256) private activePostIndex;

    /// @notice Total posts counter
    uint256 public totalPosts;

    // =========================================== Events ==========================================

    event DataPostPublished(
        bytes32 indexed postId,
        address indexed seller,
        bytes32 proofHash,
        string encryptedDataHash,
        string description,
        string category,
        uint256 priceUSDC
    );

    event DataPostUpdated(
        bytes32 indexed postId,
        string newDescription,
        uint256 newPrice
    );

    event DataPostDeactivated(
        bytes32 indexed postId,
        address indexed seller
    );

    // =========================================== Errors ==========================================

    error PostNotFound();
    error PostAlreadyExists();
    error NotPostOwner();
    error InvalidPrice();
    error InvalidDescription();

    // ========================================= Constructor ========================================

    constructor() Ownable(msg.sender) {}

    // =========================================== Functions ========================================

    /**
     * @notice Publish a data post
     * @param _proofHash SHA256 hash of raw data (proof of existence)
     * @param _encryptedDataHash IPFS CID of encrypted data
     * @param _description Description of the data
     * @param _category Category/tag for search
     * @param _priceUSDC Price in USDC (6 decimals)
     * @return postId The created post ID
     */
    function publishPost(
        bytes32 _proofHash,
        string calldata _encryptedDataHash,
        string calldata _description,
        string calldata _category,
        uint256 _priceUSDC
    ) external whenNotPaused returns (bytes32) {
        if (bytes(_description).length == 0) revert InvalidDescription();
        if (_priceUSDC == 0) revert InvalidPrice();

        // Generate post ID
        totalPosts++;
        bytes32 postId = keccak256(abi.encodePacked(
            msg.sender,
            _proofHash,
            block.timestamp,
            totalPosts
        ));

        if (posts[postId].createdAt != 0) revert PostAlreadyExists();

        // Create post
        posts[postId] = DataPost({
            postId: postId,
            seller: msg.sender,
            proofHash: _proofHash,
            encryptedDataHash: _encryptedDataHash,
            description: _description,
            category: _category,
            priceUSDC: _priceUSDC,
            createdAt: block.timestamp,
            active: true
        });

        // Add to indexes
        postsBySeller[msg.sender].push(postId);
        postsByCategory[_category].push(postId);
        activePostIndex[postId] = activePosts.length;
        activePosts.push(postId);

        emit DataPostPublished(
            postId,
            msg.sender,
            _proofHash,
            _encryptedDataHash,
            _description,
            _category,
            _priceUSDC
        );

        return postId;
    }

    /**
     * @notice Update post description and/or price
     * @param _postId Post ID
     * @param _newDescription New description (empty to keep current)
     * @param _newPrice New price (0 to keep current)
     */
    function updatePost(
        bytes32 _postId,
        string calldata _newDescription,
        uint256 _newPrice
    ) external {
        DataPost storage post = posts[_postId];
        if (post.createdAt == 0) revert PostNotFound();
        if (post.seller != msg.sender) revert NotPostOwner();

        if (bytes(_newDescription).length > 0) {
            post.description = _newDescription;
        }
        if (_newPrice > 0) {
            post.priceUSDC = _newPrice;
        }

        emit DataPostUpdated(_postId, post.description, post.priceUSDC);
    }

    /**
     * @notice Deactivate a post (stop selling)
     * @param _postId Post ID
     */
    function deactivatePost(bytes32 _postId) external {
        DataPost storage post = posts[_postId];
        if (post.createdAt == 0) revert PostNotFound();
        if (post.seller != msg.sender) revert NotPostOwner();

        post.active = false;

        // Remove from active posts
        uint256 index = activePostIndex[_postId];
        uint256 lastIndex = activePosts.length - 1;

        if (index != lastIndex) {
            bytes32 lastPostId = activePosts[lastIndex];
            activePosts[index] = lastPostId;
            activePostIndex[lastPostId] = index;
        }

        activePosts.pop();
        delete activePostIndex[_postId];

        emit DataPostDeactivated(_postId, msg.sender);
    }

    // =========================================== Discovery ========================================

    /**
     * @notice Get post by ID
     * @param _postId Post ID
     * @return Post information
     */
    function getPost(bytes32 _postId) external view returns (DataPost memory) {
        return posts[_postId];
    }

    /**
     * @notice Get all active posts
     * @return Array of active post IDs
     */
    function getActivePosts() external view returns (bytes32[] memory) {
        return activePosts;
    }

    /**
     * @notice Get posts by seller
     * @param _seller Seller address
     * @return Array of post IDs
     */
    function getPostsBySeller(address _seller) external view returns (bytes32[] memory) {
        return postsBySeller[_seller];
    }

    /**
     * @notice Get posts by category
     * @param _category Category name
     * @return Array of post IDs
     */
    function getPostsByCategory(string calldata _category) external view returns (bytes32[] memory) {
        return postsByCategory[_category];
    }

    /**
     * @notice Get total number of active posts
     * @return Count of active posts
     */
    function getActivePostCount() external view returns (uint256) {
        return activePosts.length;
    }

    // =========================================== Admin ============================================

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }
}

contracts/datasale/DataSaleEscrow.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "../registry/ShogunRelayRegistry.sol";
import "./DataPostRegistry.sol";

/**
 * @title DataSaleEscrow
 * @notice Escrow contract for encrypted data sales (inspired by Erasure Protocol)
 * @dev Manages encrypted data exchange between seller and buyer
 * 
 * Flow:
 * 1. Seller publishes DataPost
 * 2. Buyer creates escrow for the post
 * 3. Buyer deposits payment
 * 4. Seller encrypts data for buyer
 * 5. Seller submits encrypted key to escrow
 * 6. Buyer retrieves and decrypts data
 * 7. Buyer completes or disputes
 */
contract DataSaleEscrow is ReentrancyGuard {
    using SafeERC20 for IERC20;

    // =========================================== Types ===========================================

    enum EscrowStatus {
        PENDING_PAYMENT,    // Waiting for buyer payment
        ACTIVE,             // Payment deposited, waiting for seller to submit data
        DATA_SUBMITTED,     // Seller submitted encrypted key, buyer can retrieve
        COMPLETED,          // Buyer completed, funds released to seller
        DISPUTED,           // Griefing started
        CANCELLED           // Cancelled by buyer
    }

    struct EscrowInfo {
        bytes32 postId;                 // DataPost ID
        address seller;                 // Seller address (Bob)
        address buyer;                  // Buyer address (Alice)
        uint256 priceUSDC;             // Sale price
        bytes32 proofHash;              // Expected proof hash of data
        string encryptedDataHash;       // IPFS CID of encrypted data
        bytes32 encryptedSymKeyHash;    // Hash of encrypted symmetric key
        EscrowStatus status;            // Current status
        uint256 createdAt;              // Creation timestamp
        uint256 countdownEnd;           // Countdown end (for delivery deadline)
        uint256 countdownDuration;      // Countdown duration (seconds)
    }

    // =========================================== State ===========================================

    /// @notice Payment token (USDC)
    IERC20 public immutable paymentToken;

    /// @notice Registry contract (for relay/user keys and griefing)
    ShogunRelayRegistry public immutable registry;

    /// @notice DataPost registry
    DataPostRegistry public immutable postRegistry;

    /// @notice Escrow information
    EscrowInfo public escrow;

    /// @notice Buyer payment deposited
    uint256 public buyerPayment;

    /// @notice Whether seller is a relay (checked during initialization)
    bool public sellerIsRelay;

    /// @notice Whether seller is a registered user (checked during initialization)
    bool public sellerIsUser;

    // =========================================== Events ==========================================

    event EscrowCreated(
        bytes32 indexed postId,
        address indexed seller,
        address indexed buyer,
        uint256 priceUSDC
    );

    event PaymentDeposited(
        address indexed buyer,
        uint256 amount
    );

    event DataSubmitted(
        bytes32 indexed encryptedSymKeyHash
    );

    event EscrowCompleted(
        address indexed buyer,
        address indexed seller,
        uint256 amountReleased
    );

    event EscrowDisputed(
        address indexed buyer,
        uint256 slashAmount,
        string reason
    );

    event EscrowCancelled(
        address indexed buyer,
        uint256 refundAmount
    );

    // =========================================== Errors ==========================================

    error EscrowNotPending();
    error EscrowNotActive();
    error NotBuyer();
    error NotSeller();
    error NotParties();
    error InvalidAmount();
    error DataPostNotFound();
    error DataPostNotActive();
    error CountdownNotExpired(); // Legacy error name (kept for compatibility)
    error CountdownExpired(); // Countdown has expired, seller can no longer submit data
    error InvalidProofHash();

    // ========================================= Constructor ========================================

    constructor(
        address _paymentToken,
        address _registry,
        address _postRegistry
    ) {
        paymentToken = IERC20(_paymentToken);
        registry = ShogunRelayRegistry(_registry);
        postRegistry = DataPostRegistry(_postRegistry);
    }

    // =========================================== Initialization ==================================

    /**
     * @notice Initialize escrow (called by factory)
     * @param _postId DataPost ID
     * @param _seller Seller address
     * @param _buyer Buyer address
     * @param _countdownDuration Countdown duration in seconds (e.g., 7 days)
     * @dev If seller is a relay, automatically registers a deal in registry for griefing
     */
    function initialize(
        bytes32 _postId,
        address _seller,
        address _buyer,
        uint256 _countdownDuration
    ) external {
        // Can only initialize once
        require(escrow.createdAt == 0, "Already initialized");

        // Get post info
        DataPostRegistry.DataPost memory post = postRegistry.getPost(_postId);
        if (post.createdAt == 0) revert DataPostNotFound();
        if (!post.active) revert DataPostNotActive();
        if (post.seller != _seller) revert NotSeller();

        // Check if seller is a relay or user (for griefing mechanism)
        sellerIsRelay = registry.isActiveRelay(_seller);
        // Only check if user if not already a relay (relays can't be users)
        if (!sellerIsRelay) {
            // Try to get user info - if it reverts (user not registered), sellerIsUser stays false
            try registry.getUserInfo(_seller) returns (ShogunRelayRegistry.ParticipantInfo memory userInfo) {
                sellerIsUser = userInfo.registeredAt > 0;
            } catch {
                sellerIsUser = false;
            }
        } else {
            sellerIsUser = false;
        }

        // Initialize escrow
        escrow = EscrowInfo({
            postId: _postId,
            seller: _seller,
            buyer: _buyer,
            priceUSDC: post.priceUSDC,
            proofHash: post.proofHash,
            encryptedDataHash: post.encryptedDataHash,
            encryptedSymKeyHash: bytes32(0),
            status: EscrowStatus.PENDING_PAYMENT,
            createdAt: block.timestamp,
            countdownEnd: 0,
            countdownDuration: _countdownDuration
        });

        emit EscrowCreated(_postId, _seller, _buyer, post.priceUSDC);
    }

    // =========================================== Buyer Functions =================================

    /**
     * @notice Deposit payment to escrow
     * @dev Only buyer can call, must match exact price
     */
    function depositPayment() external nonReentrant {
        if (msg.sender != escrow.buyer) revert NotBuyer();
        if (escrow.status != EscrowStatus.PENDING_PAYMENT) revert EscrowNotPending();

        uint256 amount = escrow.priceUSDC;
        paymentToken.safeTransferFrom(msg.sender, address(this), amount);
        buyerPayment = amount;
        escrow.status = EscrowStatus.ACTIVE;
        escrow.countdownEnd = block.timestamp + escrow.countdownDuration;

        emit PaymentDeposited(msg.sender, amount);
    }

    /**
     * @notice Cancel escrow and refund payment (before data submission)
     * @dev Only buyer can cancel if seller hasn't submitted data yet
     */
    function cancel() external nonReentrant {
        if (msg.sender != escrow.buyer) revert NotBuyer();
        if (escrow.status != EscrowStatus.ACTIVE) revert EscrowNotActive();
        if (escrow.encryptedSymKeyHash != bytes32(0)) revert EscrowNotPending(); // Data already submitted

        uint256 refund = buyerPayment;
        buyerPayment = 0;
        escrow.status = EscrowStatus.CANCELLED;

        paymentToken.safeTransfer(escrow.buyer, refund);

        emit EscrowCancelled(escrow.buyer, refund);
    }

    /**
     * @notice Complete escrow after receiving and verifying data
     * @dev Buyer confirms data is correct and releases payment
     */
    function complete() external nonReentrant {
        if (msg.sender != escrow.buyer) revert NotBuyer();
        if (escrow.status != EscrowStatus.DATA_SUBMITTED) revert EscrowNotActive();
        if (escrow.encryptedSymKeyHash == bytes32(0)) revert EscrowNotActive();

        uint256 amount = buyerPayment;
        buyerPayment = 0;
        escrow.status = EscrowStatus.COMPLETED;

        paymentToken.safeTransfer(escrow.seller, amount);

        emit EscrowCompleted(escrow.buyer, escrow.seller, amount);
    }

    /**
     * @notice Buyer griefs seller (Erasure-style)
     * @param _slashAmount Amount to slash from seller stake (only used if seller is relay and deal exists)
     * @param _dealId Deal ID in registry (use postId if seller registered deal with same ID, or bytes32(0) to skip relay griefing)
     * @param _reason Reason for griefing
     * @dev Always refunds buyer. If seller is relay and deal exists, also griefs relay via registry
     */
    function grief(
        uint256 _slashAmount,
        bytes32 _dealId,
        string calldata _reason
    ) external nonReentrant {
        if (msg.sender != escrow.buyer) revert NotBuyer();
        if (escrow.status == EscrowStatus.COMPLETED || escrow.status == EscrowStatus.CANCELLED) {
            revert EscrowNotActive();
        }

        // Mark escrow as disputed
        escrow.status = EscrowStatus.DISPUTED;

        // Calculate griefing cost if needed (before refunding)
        uint256 griefingCost = 0;
        if (_slashAmount > 0) {
            if (sellerIsRelay) {
                uint256 griefingRatio = registry.defaultGriefingRatio();
                griefingCost = (_slashAmount * griefingRatio) / 10000;
            } else if (sellerIsUser) {
                // Get user info to calculate cost
                try registry.getUserInfo(escrow.seller) returns (ShogunRelayRegistry.ParticipantInfo memory userInfo) {
                    griefingCost = (_slashAmount * userInfo.griefingRatio) / 10000;
                } catch {
                    // User not registered or error - no cost
                    griefingCost = 0;
                }
            }
        }

        // Refund buyer payment (full amount - buyer will pay griefing cost separately)
        uint256 refundAmount = buyerPayment;
        if (refundAmount > 0) {
            buyerPayment = 0;
            paymentToken.safeTransfer(escrow.buyer, refundAmount);
        }

        // Grief seller if they have stake (relay or user)
        // Buyer must pay griefing cost - they need to approve escrow to transfer it
        if (_slashAmount > 0 && griefingCost > 0) {
            // Transfer griefing cost from buyer to this contract (will be forwarded to registry)
            // Buyer must have approved escrow for griefing cost
            paymentToken.safeTransferFrom(escrow.buyer, address(this), griefingCost);

            if (sellerIsRelay) {
                // Grief relay via registry
                bytes32 dealIdToUse = _dealId == bytes32(0) ? escrow.postId : _dealId;
                uint256 griefingRatio = registry.defaultGriefingRatio();

                // Approve registry to spend griefing cost from escrow
                paymentToken.approve(address(registry), griefingCost);

                try registry.grief(escrow.seller, _slashAmount, _reason, griefingRatio, dealIdToUse) {
                    // Griefing successful
                } catch {
                    // Griefing failed - refund cost to buyer
                    paymentToken.safeTransfer(escrow.buyer, griefingCost);
                }

                paymentToken.approve(address(registry), 0);
            } else if (sellerIsUser) {
                // Grief user directly
                paymentToken.approve(address(registry), griefingCost);

                try registry.griefUser(escrow.seller, _slashAmount, _reason) {
                    // Griefing successful
                } catch {
                    // Griefing failed - refund cost to buyer
                    paymentToken.safeTransfer(escrow.buyer, griefingCost);
                }

                paymentToken.approve(address(registry), 0);
            }
        }

        emit EscrowDisputed(escrow.buyer, _slashAmount, _reason);
    }

    // =========================================== Seller Functions =================================

    /**
     * @notice Seller submits encrypted symmetric key
     * @param _encryptedSymKeyHash Hash of encrypted symmetric key (IPFS CID or hash)
     * @dev Seller encrypts SymKey with buyer's public key and submits hash
     *      Seller must submit before countdown expires
     */
    function submitData(
        bytes32 _encryptedSymKeyHash
    ) external {
        if (msg.sender != escrow.seller) revert NotSeller();
        if (escrow.status != EscrowStatus.ACTIVE) revert EscrowNotActive();
        // Seller must submit data BEFORE countdown expires
        if (escrow.countdownEnd > 0 && block.timestamp > escrow.countdownEnd) {
            revert CountdownExpired(); // Countdown expired, too late to submit
        }

        escrow.encryptedSymKeyHash = _encryptedSymKeyHash;
        escrow.status = EscrowStatus.DATA_SUBMITTED;

        emit DataSubmitted(_encryptedSymKeyHash);
    }

    // =========================================== View Functions ==================================

    /**
     * @notice Get escrow information
     * @return Escrow information struct
     */
    function getEscrowInfo() external view returns (EscrowInfo memory) {
        return escrow;
    }

    /**
     * @notice Check if countdown has expired
     * @return True if countdown expired
     */
    function isCountdownExpired() external view returns (bool) {
        return block.timestamp > escrow.countdownEnd && escrow.countdownEnd > 0;
    }
}

contracts/datasale/DataSaleEscrowFactory.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "./DataSaleEscrow.sol";

/**
 * @title DataSaleEscrowFactory
 * @notice Factory for creating DataSaleEscrow instances using EIP-1167 Minimal Proxy pattern
 * @dev Uses cloning to reduce gas costs significantly (from ~500k to ~45k gas per escrow)
 * 
 * EIP-1167 Minimal Proxy bytecode:
 * 0x363d3d373d3d3d363d73<implementation>5af43d82803e903d91602b57fd5bf3
 * 
 * Token Support:
 * - Current: Single payment token (immutable, set at deployment)
 * - Future: To support new tokens, deploy new factory with new token address
 * - Alternative: Deploy TokenRegistry and create new factory version that uses it
 */
contract DataSaleEscrowFactory {
    // =========================================== State ===========================================

    /// @notice Implementation contract (used for cloning)
    address public immutable implementation;
    
    /// @notice Template escrow contract (kept for backward compatibility)
    address public immutable template;

    /// @notice All created escrows (addresses of minimal proxies)
    address[] public escrows;

    /// @notice Escrows by buyer
    mapping(address => address[]) public escrowsByBuyer;

    /// @notice Escrows by seller
    mapping(address => address[]) public escrowsBySeller;

    /// @notice Escrows by post ID
    mapping(bytes32 => address[]) public escrowsByPost;

    // =========================================== Events ==========================================

    event EscrowCreated(
        address indexed escrow,
        bytes32 indexed postId,
        address indexed seller,
        address buyer,
        uint256 priceUSDC
    );

    // ========================================= Constructor ========================================

    constructor(address _paymentToken, address _registry, address _postRegistry) {
        // Deploy implementation contract (used for cloning)
        DataSaleEscrow implContract = new DataSaleEscrow(_paymentToken, _registry, _postRegistry);
        implementation = address(implContract);
        template = address(implContract); // Keep for backward compatibility
    }

    // =========================================== Functions ========================================

    /**
     * @notice Create a new escrow for a data sale using EIP-1167 Minimal Proxy
     * @param _postId DataPost ID
     * @param _seller Seller address
     * @param _countdownDuration Countdown duration in seconds (e.g., 7 days = 604800)
     * @return escrow Address of created escrow (minimal proxy)
     * @dev Uses EIP-1167 cloning pattern to reduce gas costs from ~500k to ~45k per escrow
     */
    function createEscrow(
        bytes32 _postId,
        address _seller,
        uint256 _countdownDuration
    ) external returns (address escrow) {
        // Get post to verify it exists
        DataPostRegistry postRegistry = DataSaleEscrow(implementation).postRegistry();
        DataPostRegistry.DataPost memory post = postRegistry.getPost(_postId);
        
        require(post.createdAt != 0, "Post not found");
        require(post.active, "Post not active");
        require(post.seller == _seller, "Invalid seller");

        // Create minimal proxy using EIP-1167
        bytes memory bytecode = _generateMinimalProxyBytecode(implementation);
        bytes32 salt = keccak256(abi.encodePacked(_postId, _seller, msg.sender, block.timestamp));
        
        assembly {
            escrow := create2(0, add(bytecode, 0x20), mload(bytecode), salt)
        }
        
        require(escrow != address(0), "Failed to create proxy");

        // Initialize escrow
        DataSaleEscrow(escrow).initialize(_postId, _seller, msg.sender, _countdownDuration);

        escrows.push(escrow);
        escrowsByBuyer[msg.sender].push(escrow);
        escrowsBySeller[_seller].push(escrow);
        escrowsByPost[_postId].push(escrow);

        emit EscrowCreated(escrow, _postId, _seller, msg.sender, post.priceUSDC);

        return escrow;
    }

    /**
     * @notice Generate EIP-1167 Minimal Proxy bytecode
     * @param _implementation Address of implementation contract
     * @return bytecode Complete bytecode for minimal proxy
     * @dev EIP-1167 format: 0x363d3d373d3d3d363d73<20-byte-address>5af43d82803e903d91602b57fd5bf3
     */
    function _generateMinimalProxyBytecode(address _implementation) internal pure returns (bytes memory) {
        bytes20 implementationBytes = bytes20(_implementation);
        bytes memory bytecode = abi.encodePacked(
            hex"3d602d80600a3d3981f3363d3d373d3d3d363d73",
            implementationBytes,
            hex"5af43d82803e903d91602b57fd5bf3"
        );
        return bytecode;
    }

    /**
     * @notice Get all escrows
     * @return Array of escrow addresses (minimal proxy addresses)
     */
    function getAllEscrows() external view returns (address[] memory) {
        return escrows;
    }

    /**
     * @notice Get escrows by buyer
     * @param _buyer Buyer address
     * @return Array of escrow addresses
     */
    function getEscrowsByBuyer(address _buyer) external view returns (address[] memory) {
        return escrowsByBuyer[_buyer];
    }

    /**
     * @notice Get escrows by seller
     * @param _seller Seller address
     * @return Array of escrow addresses
     */
    function getEscrowsBySeller(address _seller) external view returns (address[] memory) {
        return escrowsBySeller[_seller];
    }

    /**
     * @notice Get escrows by post ID
     * @param _postId Post ID
     * @return Array of escrow addresses
     */
    function getEscrowsByPost(bytes32 _postId) external view returns (address[] memory) {
        return escrowsByPost[_postId];
    }

    /**
     * @notice Get total number of escrows
     * @return Count of escrows
     */
    function getEscrowCount() external view returns (uint256) {
        return escrows.length;
    }
}

contracts/oracle/OracleFeedRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "../registry/ShogunRelayRegistry.sol";

/**
 * @title OracleFeedRegistry
 * @notice Registry for oracle data feeds provided by Shogun relays
 * @dev Allows relays to register custom data feeds with pricing and schema information
 *      Separate contract to avoid redeploying ShogunRelayRegistry
 */
contract OracleFeedRegistry {
    // =========================================== Types ===========================================

    /// @notice Supported data types for feed payloads
    enum DataType {
        PRICE,      // Simple price value (uint256)
        STRING,     // String data
        JSON,       // JSON-encoded data
        BYTES,      // Raw bytes
        CUSTOM      // Custom ABI-encoded data
    }

    /// @notice Feed configuration
    struct FeedInfo {
        string name;              // Human-readable name (e.g., "ETH/USD", "weather/rome")
        DataType dataType;        // Type of data in payload
        string schema;            // ABI or JSON schema for decoding payload
        uint256 priceAtomic;      // Cost per request in USDC (6 decimals)
        uint256 updateFreqSecs;   // Expected update frequency
        uint256 createdAt;        // Registration timestamp
        bool active;              // Whether feed is active
    }

    // =========================================== State ===========================================

    /// @notice ShogunRelayRegistry for verifying active relays
    ShogunRelayRegistry public immutable relayRegistry;

    /// @notice Relay address => feedId => FeedInfo
    mapping(address => mapping(bytes32 => FeedInfo)) public relayFeeds;

    /// @notice Relay address => list of feedIds
    mapping(address => bytes32[]) public relayFeedIds;

    /// @notice Total number of registered feeds across all relays
    uint256 public totalFeeds;

    // =========================================== Events ===========================================

    event FeedRegistered(
        address indexed relay,
        bytes32 indexed feedId,
        string name,
        DataType dataType,
        uint256 price
    );

    event FeedUpdated(
        address indexed relay,
        bytes32 indexed feedId,
        uint256 newPrice,
        bool active
    );

    event FeedDeactivated(
        address indexed relay,
        bytes32 indexed feedId
    );

    // =========================================== Errors ===========================================

    error NotActiveRelay();
    error FeedAlreadyExists();
    error FeedNotFound();
    error InvalidName();

    // =========================================== Constructor ===========================================

    /// @param _relayRegistry Address of ShogunRelayRegistry contract
    constructor(address _relayRegistry) {
        require(_relayRegistry != address(0), "OracleFeedRegistry: Invalid registry");
        relayRegistry = ShogunRelayRegistry(_relayRegistry);
    }

    // =========================================== Feed Management ===========================================

    /// @notice Register a new data feed
    /// @param _name Feed name (used to compute feedId)
    /// @param _dataType Type of data in payload
    /// @param _schema ABI or JSON schema for decoding
    /// @param _priceAtomic Cost per request in USDC atomic units (6 decimals)
    /// @param _updateFreqSecs Expected update frequency in seconds
    function registerFeed(
        string calldata _name,
        DataType _dataType,
        string calldata _schema,
        uint256 _priceAtomic,
        uint256 _updateFreqSecs
    ) external {
        if (!relayRegistry.isActiveRelay(msg.sender)) revert NotActiveRelay();
        if (bytes(_name).length == 0) revert InvalidName();

        bytes32 feedId = keccak256(bytes(_name));
        
        // Check if feed already exists for this relay
        if (relayFeeds[msg.sender][feedId].createdAt != 0) revert FeedAlreadyExists();

        relayFeeds[msg.sender][feedId] = FeedInfo({
            name: _name,
            dataType: _dataType,
            schema: _schema,
            priceAtomic: _priceAtomic,
            updateFreqSecs: _updateFreqSecs,
            createdAt: block.timestamp,
            active: true
        });

        relayFeedIds[msg.sender].push(feedId);
        totalFeeds++;

        emit FeedRegistered(msg.sender, feedId, _name, _dataType, _priceAtomic);
    }

    /// @notice Update feed pricing and status
    /// @param _feedId Feed identifier
    /// @param _newPrice New price in USDC atomic units
    /// @param _active Whether feed should be active
    function updateFeed(
        bytes32 _feedId,
        uint256 _newPrice,
        bool _active
    ) external {
        if (!relayRegistry.isActiveRelay(msg.sender)) revert NotActiveRelay();
        if (relayFeeds[msg.sender][_feedId].createdAt == 0) revert FeedNotFound();

        relayFeeds[msg.sender][_feedId].priceAtomic = _newPrice;
        relayFeeds[msg.sender][_feedId].active = _active;

        emit FeedUpdated(msg.sender, _feedId, _newPrice, _active);
    }

    /// @notice Deactivate a feed
    /// @param _feedId Feed identifier
    function deactivateFeed(bytes32 _feedId) external {
        if (relayFeeds[msg.sender][_feedId].createdAt == 0) revert FeedNotFound();
        
        relayFeeds[msg.sender][_feedId].active = false;
        
        emit FeedDeactivated(msg.sender, _feedId);
    }

    // =========================================== View Functions ===========================================

    /// @notice Get all feeds for a relay
    /// @param _relay Relay address
    /// @return feeds Array of FeedInfo structs
    function getRelayFeeds(address _relay) external view returns (FeedInfo[] memory feeds) {
        bytes32[] memory feedIds = relayFeedIds[_relay];
        feeds = new FeedInfo[](feedIds.length);
        
        for (uint256 i = 0; i < feedIds.length; i++) {
            feeds[i] = relayFeeds[_relay][feedIds[i]];
        }
    }

    /// @notice Get feed info by relay and feedId
    /// @param _relay Relay address
    /// @param _feedId Feed identifier
    /// @return Feed information
    function getFeed(address _relay, bytes32 _feedId) external view returns (FeedInfo memory) {
        return relayFeeds[_relay][_feedId];
    }

    /// @notice Get feedId from name
    /// @param _name Feed name
    /// @return feedId Computed feed identifier
    function getFeedId(string calldata _name) external pure returns (bytes32) {
        return keccak256(bytes(_name));
    }

    /// @notice Get number of feeds for a relay
    /// @param _relay Relay address
    /// @return count Number of registered feeds
    function getRelayFeedCount(address _relay) external view returns (uint256) {
        return relayFeedIds[_relay].length;
    }

    /// @notice Check if a feed exists and is active
    /// @param _relay Relay address
    /// @param _feedId Feed identifier
    /// @return exists Whether feed exists
    /// @return active Whether feed is active
    function isFeedActive(address _relay, bytes32 _feedId) 
        external 
        view 
        returns (bool exists, bool active) 
    {
        FeedInfo memory feed = relayFeeds[_relay][_feedId];
        exists = feed.createdAt != 0;
        active = feed.active;
    }
}

contracts/oracle/ShogunOracle.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "../registry/ShogunRelayRegistry.sol";

/**
 * @title ShogunOracle
 * @notice Trust-minimized oracle for accessing offchain data onchain
 * @dev Extends Trustus pattern with ShogunRelayRegistry integration
 *      Only registered active relays can sign valid oracle packets
 * 
 * Based on: https://github.com/ZeframLou/trustus
 */
abstract contract ShogunOracle {
    // =========================================== Structs ===========================================

    /// @notice Oracle packet with EIP-712 signature
    /// @param v Part of the ECDSA signature
    /// @param r Part of the ECDSA signature
    /// @param s Part of the ECDSA signature
    /// @param feedId Identifier for the data feed (keccak256 of feed name)
    /// @param deadline Unix timestamp after which packet should be rejected
    /// @param payload ABI-encoded data payload
    struct OraclePacket {
        uint8 v;
        bytes32 r;
        bytes32 s;
        bytes32 feedId;
        uint256 deadline;
        bytes payload;
    }

    // =========================================== Errors ===========================================

    error ShogunOracle__InvalidPacket();
    error ShogunOracle__PacketExpired();
    error ShogunOracle__SignerNotActiveRelay();

    // =========================================== Immutables ===========================================

    /// @notice The chain ID used by EIP-712
    uint256 internal immutable INITIAL_CHAIN_ID;

    /// @notice The domain separator used by EIP-712
    bytes32 internal immutable INITIAL_DOMAIN_SEPARATOR;

    /// @notice ShogunRelayRegistry for verifying signers
    ShogunRelayRegistry public immutable relayRegistry;

    // =========================================== Constants ===========================================

    /// @notice EIP-712 typehash for OraclePacket
    bytes32 public constant ORACLE_PACKET_TYPEHASH = keccak256(
        "OraclePacket(bytes32 feedId,uint256 deadline,bytes payload)"
    );

    // =========================================== Modifiers ===========================================

    /// @notice Verifies whether an oracle packet is valid
    /// @dev Checks deadline, signature, and that signer is an active relay
    /// @param feedId Expected feed identifier
    /// @param packet The oracle packet to verify
    modifier verifyOraclePacket(bytes32 feedId, OraclePacket calldata packet) {
        if (!_verifyPacket(feedId, packet)) revert ShogunOracle__InvalidPacket();
        _;
    }

    // =========================================== Constructor ===========================================

    /// @param _relayRegistry Address of ShogunRelayRegistry contract
    constructor(address _relayRegistry) {
        require(_relayRegistry != address(0), "ShogunOracle: Invalid registry");
        relayRegistry = ShogunRelayRegistry(_relayRegistry);
        INITIAL_CHAIN_ID = block.chainid;
        INITIAL_DOMAIN_SEPARATOR = _computeDomainSeparator();
    }

    // =========================================== Verification ===========================================

    /// @notice Verifies whether an oracle packet is valid
    /// @param feedId Expected feed identifier
    /// @param packet The oracle packet to verify
    /// @return success True if packet is valid
    function _verifyPacket(bytes32 feedId, OraclePacket calldata packet)
        internal
        view
        virtual
        returns (bool success)
    {
        // Verify deadline
        if (block.timestamp > packet.deadline) return false;

        // Verify feedId matches
        if (feedId != packet.feedId) return false;

        // Recover signer from signature
        address signer = ecrecover(
            keccak256(
                abi.encodePacked(
                    "\x19\x01",
                    DOMAIN_SEPARATOR(),
                    keccak256(
                        abi.encode(
                            ORACLE_PACKET_TYPEHASH,
                            packet.feedId,
                            packet.deadline,
                            keccak256(packet.payload)
                        )
                    )
                )
            ),
            packet.v,
            packet.r,
            packet.s
        );

        // Verify signer is valid and is an active relay
        return (signer != address(0)) && relayRegistry.isActiveRelay(signer);
    }

    /// @notice Get the signer of an oracle packet (without verification)
    /// @param packet The oracle packet
    /// @return signer The recovered signer address
    function getPacketSigner(OraclePacket calldata packet) 
        public 
        view 
        returns (address signer) 
    {
        signer = ecrecover(
            keccak256(
                abi.encodePacked(
                    "\x19\x01",
                    DOMAIN_SEPARATOR(),
                    keccak256(
                        abi.encode(
                            ORACLE_PACKET_TYPEHASH,
                            packet.feedId,
                            packet.deadline,
                            keccak256(packet.payload)
                        )
                    )
                )
            ),
            packet.v,
            packet.r,
            packet.s
        );
    }

    // =========================================== EIP-712 ===========================================

    /// @notice The domain separator used by EIP-712
    function DOMAIN_SEPARATOR() public view virtual returns (bytes32) {
        return block.chainid == INITIAL_CHAIN_ID
            ? INITIAL_DOMAIN_SEPARATOR
            : _computeDomainSeparator();
    }

    /// @notice Computes the domain separator used by EIP-712
    function _computeDomainSeparator() internal view virtual returns (bytes32) {
        return keccak256(
            abi.encode(
                keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"),
                keccak256("ShogunOracle"),
                keccak256("1"),
                block.chainid,
                address(this)
            )
        );
    }
}

contracts/registry/ShogunRelayRegistry.s.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/**
 * @title ShogunRelayRegistry
 * @notice On-chain registry for Shogun participants (relays and users)
 * @dev Manages participant registration, staking, and griefing-based slashing
 * 
 * Features:
 * - Participant registration (relays with endpoint, users without)
 * - Unified stake management for relays and users
 * - Decentralized griefing-based slashing (Erasure-style, no owner required)
 * - Discovery of active relays and users
 * - Encryption keys (pubkey/epub) for encrypted data exchange
 * 
 * Architecture:
 * - Relays: endpoint required, can unstake with delay
 * - Users: no endpoint, can deposit/withdraw stake freely
 * - Both can be griefed if they have stake
 * 
 * ENCRYPTION KEYS FORMAT:
 * - pubkey/epub are stored as bytes in the contract
 * - Off-chain, they are interpreted as extended JSON format
 * - Standard format: GunDB SEA format ("x.y" coordinates)
 * - Alternative: JWK (JSON Web Key) standard format
 */
contract ShogunRelayRegistry is Ownable, ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;

    // =========================================== Types ===========================================

    /// @notice Participant status enum (unified for relay and users)
    enum ParticipantStatus {
        Inactive,       // Not registered or deactivated
        Active,         // Registered and operational
        Unstaking,      // In unstaking period (relays only)
        Slashed         // Slashed and banned
    }

    /// @notice Unified participant information (relay or user)
    /// @dev For users: endpoint is empty string, unstakeRequestedAt is 0
    struct ParticipantInfo {
        address owner;              // Participant address (relay operator or user)
        string endpoint;            // HTTP/WebSocket endpoint URL (empty "" for users = null)
        bytes pubkey;               // GunDB public key (ECDSA, JSON format: "x.y") for verification and encryption
        bytes epub;                 // Ephemeral encryption public key (ECDH, JSON format: "x.y")
        uint256 stakedAmount;       // USDC staked
        uint256 registeredAt;       // Registration timestamp
        uint256 updatedAt;          // Last update timestamp
        uint256 unstakeRequestedAt; // Unstake request timestamp (0 if not unstaking, 0 for users)
        ParticipantStatus status;   // Current status
        uint256 totalSlashed;       // Total amount slashed
        uint256 griefingRatio;      // Cost to slash 1 USDC (in basis points, e.g., 100 = 0.01 USDC cost per 1 USDC slashed)
    }

    /// @notice Slash report
    struct SlashReport {
        bytes32 reportId;           // Unique report identifier
        address reporter;           // Who reported the violation
        address relay;              // Relay being reported
        bytes32 dealId;             // Related deal (if any)
        string reason;              // Reason for slash
        uint256 amount;             // Amount slashed from relay
        uint256 cost;               // Cost paid by reporter
        uint256 timestamp;          // When slash occurred
    }

    // =========================================== State ===========================================

    /// @notice USDC token contract (Base Sepolia)
    /// @dev Immutable for security. To support new tokens, deploy new registry version.
    ///      Future: Can integrate TokenRegistry for multi-token support via upgradeable pattern.
    IERC20 public immutable stakingToken;

    /// @notice Minimum stake required to register as a relay
    uint256 public minStake;
    
    /// @notice Optional TokenRegistry for future multi-token support
    /// @dev Can be set by owner to enable multi-token functionality in future versions
    ///      If set, allows using multiple tokens for staking (requires contract modifications)
    address public tokenRegistry;

    /// @notice Unstaking delay period (seconds)
    uint256 public unstakingDelay;

    /// @notice Default griefing ratio for clients without stake (basis points)
    /// e.g., 500 = 0.05 USDC cost to slash 1 USDC from relay
    uint256 public defaultGriefingRatio;

    /// @notice Griefing ratio for clients with stake (basis points, typically lower)
    uint256 public stakedClientGriefingRatio;

    /// @notice All participants (relays and users) - unified registry
    mapping(address => ParticipantInfo) public participants;

    /// @notice Slash reports
    mapping(bytes32 => SlashReport) public slashReports;

    /// @notice Active relay addresses (for discovery)
    address[] public activeRelays;

    /// @notice Index in activeRelays array
    mapping(address => uint256) private activeRelayIndex;

    /// @notice Active participant addresses (for discovery - includes relays and users)
    address[] public activeParticipants;

    /// @notice Index in activeParticipants array
    mapping(address => uint256) private activeParticipantIndex;

    /// @notice Total reports counter
    uint256 public totalReports;

    /// @notice Treasury address (receives slashed amounts, can be zero address for burning)
    address public treasury;

    /// @notice Burn address for tokens (when treasury is zero address)
    /// @dev Standard Ethereum burn address: 0x000000000000000000000000000000000000dEaD
    address private constant BURN_ADDRESS = 0x000000000000000000000000000000000000dEaD;

    // =========================================== Events ==========================================

    event RelayRegistered(
        address indexed relay,
        address indexed owner,
        string endpoint,
        uint256 stakedAmount
    );

    event RelayUpdated(
        address indexed relay,
        string newEndpoint
    );

    event RelayEncryptionKeysUpdated(
        address indexed relay,
        bytes pubkey,
        bytes epub
    );

    event StakeIncreased(
        address indexed relay,
        uint256 amount,
        uint256 newTotal
    );

    event UnstakeRequested(
        address indexed relay,
        uint256 amount,
        uint256 availableAt
    );

    event StakeWithdrawn(
        address indexed relay,
        uint256 amount
    );

    event RelayDeactivated(
        address indexed relay,
        string reason
    );

    event RelaySlashed(
        bytes32 indexed reportId,
        address indexed relay,
        address indexed reporter,
        uint256 amount,
        uint256 cost,
        string reason
    );

    event UserRegistered(
        address indexed user,
        bytes pubkey,
        bytes epub
    );

    event UserKeysUpdated(
        address indexed user,
        bytes pubkey,
        bytes epub
    );

    event UserStakeDeposited(
        address indexed user,
        uint256 amount,
        uint256 totalStake
    );

    event UserStakeWithdrawn(
        address indexed user,
        uint256 amount,
        uint256 remainingStake
    );

    event UserSlashed(
        bytes32 indexed reportId,
        address indexed user,
        address indexed reporter,
        uint256 amount,
        uint256 cost,
        string reason
    );

    // =========================================== Errors ==========================================

    error InsufficientStake();
    error RelayAlreadyRegistered();
    error RelayNotRegistered();
    error RelayNotActive();
    error UnstakingNotRequested();
    error UnstakingDelayNotPassed();
    error InvalidEndpoint();
    error InvalidAmount();
    error RelayAlreadySlashed();
    error InvalidSlashAmount();
    error InsufficientGriefingCost();
    error InvalidPubkey();
    error InvalidEpub();
    error UserNotRegistered();

    // ========================================= Constructor ========================================

    /**
     * @notice Initialize the registry
     * @param _stakingToken USDC token address on Base Sepolia
     * @param _minStake Minimum stake in USDC (6 decimals)
     * @param _unstakingDelay Delay before stake can be withdrawn (seconds)
     * @param _treasury Treasury address (zero address = burn slashed tokens)
     */
    constructor(
        address _stakingToken,
        uint256 _minStake,
        uint256 _unstakingDelay,
        address _treasury
    ) Ownable(msg.sender) {
        stakingToken = IERC20(_stakingToken);
        minStake = _minStake;
        unstakingDelay = _unstakingDelay;
        treasury = _treasury;
        
        // Default griefing ratios (basis points)
        defaultGriefingRatio = 500;        // 0.05 USDC cost per 1 USDC slashed (5%)
        stakedClientGriefingRatio = 100;   // 0.01 USDC cost per 1 USDC slashed (1%) for staked clients
    }

    // ====================================== Relay Management =====================================

    /**
     * @notice Register as a relay operator
     * @param _endpoint HTTP/WebSocket endpoint URL
     * @param _pubkey GunDB public key (ECDSA, bytes, JSON format: "x.y") for verification and encryption
     * @param _epub Ephemeral encryption public key (ECDH, bytes, JSON format: "x.y")
     * @param _stakeAmount Amount of USDC to stake
     * @param _griefingRatio Custom griefing ratio (0 to use default)
     * @dev pubkey/epub stored as bytes, interpreted as extended JSON off-chain (GunDB SEA format)
     */
    function registerRelay(
        string calldata _endpoint,
        bytes calldata _pubkey,
        bytes calldata _epub,
        uint256 _stakeAmount,
        uint256 _griefingRatio
    ) external nonReentrant whenNotPaused {
        if (bytes(_endpoint).length == 0) revert InvalidEndpoint();
        if (_stakeAmount < minStake) revert InsufficientStake();
        if (participants[msg.sender].status != ParticipantStatus.Inactive) revert RelayAlreadyRegistered();

        // Transfer stake
        stakingToken.safeTransferFrom(msg.sender, address(this), _stakeAmount);

        // Use custom ratio or default
        uint256 griefingRatio = _griefingRatio > 0 ? _griefingRatio : defaultGriefingRatio;

        // Create participant info (relay)
        participants[msg.sender] = ParticipantInfo({
            owner: msg.sender,
            endpoint: _endpoint,
            pubkey: _pubkey,
            epub: _epub,
            stakedAmount: _stakeAmount,
            registeredAt: block.timestamp,
            updatedAt: block.timestamp,
            unstakeRequestedAt: 0,
            status: ParticipantStatus.Active,
            totalSlashed: 0,
            griefingRatio: griefingRatio
        });

        // Add to active relays
        activeRelayIndex[msg.sender] = activeRelays.length;
        activeRelays.push(msg.sender);

        emit RelayRegistered(msg.sender, msg.sender, _endpoint, _stakeAmount);
        if (_pubkey.length > 0 || _epub.length > 0) {
            emit RelayEncryptionKeysUpdated(msg.sender, _pubkey, _epub);
        }
    }

    /**
     * @notice Update relay endpoint
     * @param _newEndpoint New endpoint URL (empty to keep current)
     */
    function updateRelay(
        string calldata _newEndpoint
    ) external {
        ParticipantInfo storage participant = participants[msg.sender];
        if (participant.status != ParticipantStatus.Active) revert RelayNotActive();
        if (bytes(participant.endpoint).length == 0) revert RelayNotActive(); // Must be relay

        if (bytes(_newEndpoint).length > 0) {
            participant.endpoint = _newEndpoint;
            participant.updatedAt = block.timestamp;
        }

        emit RelayUpdated(msg.sender, participant.endpoint);
    }

    /**
     * @notice Update relay encryption keys
     * @param _pubkey New encryption public key (empty to keep current)
     * @param _epub New ephemeral encryption public key (empty to keep current)
     */
    function updateRelayEncryptionKeys(
        bytes calldata _pubkey,
        bytes calldata _epub
    ) external {
        ParticipantInfo storage participant = participants[msg.sender];
        if (participant.status != ParticipantStatus.Active) revert RelayNotActive();
        if (bytes(participant.endpoint).length == 0) revert RelayNotActive(); // Must be relay
        
        if (_pubkey.length > 0) {
            participant.pubkey = _pubkey;
        }
        if (_epub.length > 0) {
            participant.epub = _epub;
        }
        
        participant.updatedAt = block.timestamp;
        emit RelayEncryptionKeysUpdated(msg.sender, participant.pubkey, participant.epub);
    }

    /**
     * @notice Increase stake amount
     * @param _amount Additional USDC to stake
     */
    function increaseStake(uint256 _amount) external nonReentrant {
        if (_amount == 0) revert InvalidAmount();
        ParticipantInfo storage participant = participants[msg.sender];
        if (participant.status == ParticipantStatus.Inactive) revert RelayNotRegistered();
        if (participant.status == ParticipantStatus.Slashed) revert RelayAlreadySlashed();

        stakingToken.safeTransferFrom(msg.sender, address(this), _amount);
        participant.stakedAmount += _amount;

        // If was unstaking, cancel unstaking and re-add to active list (relays only)
        if (participant.status == ParticipantStatus.Unstaking && bytes(participant.endpoint).length > 0) {
            participant.status = ParticipantStatus.Active;
            participant.unstakeRequestedAt = 0;
            // Re-add to active relays list
            activeRelayIndex[msg.sender] = activeRelays.length;
            activeRelays.push(msg.sender);
        }

        participant.updatedAt = block.timestamp;
        emit StakeIncreased(msg.sender, _amount, participant.stakedAmount);
    }

    /**
     * @notice Request to unstake and deactivate relay
     */
    function requestUnstake() external {
        ParticipantInfo storage participant = participants[msg.sender];
        if (participant.status != ParticipantStatus.Active) revert RelayNotActive();
        if (bytes(participant.endpoint).length == 0) revert RelayNotActive(); // Only relays can unstake

        participant.status = ParticipantStatus.Unstaking;
        participant.unstakeRequestedAt = block.timestamp;

        // Remove from active relays
        _removeFromActiveRelays(msg.sender);

        emit UnstakeRequested(
            msg.sender,
            participant.stakedAmount,
            block.timestamp + unstakingDelay
        );
    }

    /**
     * @notice Withdraw stake after unstaking delay
     */
    function withdrawStake() external nonReentrant {
        ParticipantInfo storage participant = participants[msg.sender];
        if (participant.status != ParticipantStatus.Unstaking) revert UnstakingNotRequested();
        if (bytes(participant.endpoint).length == 0) revert UnstakingNotRequested(); // Only relays can unstake
        if (block.timestamp < participant.unstakeRequestedAt + unstakingDelay) {
            revert UnstakingDelayNotPassed();
        }

        uint256 amount = participant.stakedAmount;
        participant.stakedAmount = 0;
        participant.status = ParticipantStatus.Inactive;
        participant.unstakeRequestedAt = 0;

        stakingToken.safeTransfer(msg.sender, amount);

        emit StakeWithdrawn(msg.sender, amount);
    }

    // ========================================== Slashing ==========================================

    /**
     * @notice Grief a relay (Erasure-style griefing)
     * @param _relay Relay address to grief
     * @param _slashAmount Amount to slash from relay stake (in USDC atomic units)
     * @param _reason Reason for griefing
     * @param _griefingRatio Optional griefing ratio (0 to use relay's default)
     * @param _dealId Optional deal ID for reference (can be bytes32(0))
     * @dev Reporter pays griefing cost proportional to slash amount
     *      Can be called by StorageDealRegistry or directly by clients
     */
    function grief(
        address _relay,
        uint256 _slashAmount,
        string calldata _reason,
        uint256 _griefingRatio,
        bytes32 _dealId
    ) external nonReentrant {
        ParticipantInfo storage participant = participants[_relay];
        if (participant.status == ParticipantStatus.Inactive) revert RelayNotRegistered();
        if (participant.status == ParticipantStatus.Slashed) revert RelayAlreadySlashed();
        if (bytes(participant.endpoint).length == 0) revert RelayNotRegistered(); // Must be relay
        
        // Validate slash amount
        if (_slashAmount == 0) revert InvalidSlashAmount();
        if (_slashAmount > participant.stakedAmount) revert InvalidSlashAmount();

        // Determine griefing ratio: use provided, relay's default, or global default
        uint256 griefingRatio = _griefingRatio > 0 
            ? _griefingRatio 
            : (participant.griefingRatio > 0 ? participant.griefingRatio : defaultGriefingRatio);

        // Calculate cost: griefingRatio basis points of slashAmount
        uint256 cost = (_slashAmount * griefingRatio) / 10000;
        
        // Transfer cost from reporter
        stakingToken.safeTransferFrom(msg.sender, address(this), cost);

        // Slash relay stake
        participant.stakedAmount -= _slashAmount;
        participant.totalSlashed += _slashAmount;

        // Generate report ID
        totalReports++;
        bytes32 reportId = keccak256(abi.encodePacked(
            _relay,
            msg.sender,
            block.timestamp,
            totalReports
        ));

        slashReports[reportId] = SlashReport({
            reportId: reportId,
            reporter: msg.sender,
            relay: _relay,
            dealId: _dealId,
            reason: _reason,
            amount: _slashAmount,
            cost: cost,
            timestamp: block.timestamp
        });

        // If stake falls below minimum, deactivate
        if (participant.stakedAmount < minStake) {
            if (participant.status == ParticipantStatus.Active) {
                _removeFromActiveRelays(_relay);
            }
            participant.status = ParticipantStatus.Slashed;
            emit RelayDeactivated(_relay, "Stake below minimum after slash");
        }

        // Transfer slashed amount and cost to treasury (or burn address)
        // Note: USDC doesn't support burn(), so we use a dedicated burn address
        address recipient = treasury != address(0) ? treasury : BURN_ADDRESS;
        
        stakingToken.safeTransfer(recipient, _slashAmount);
        stakingToken.safeTransfer(recipient, cost);

        emit RelaySlashed(reportId, _relay, msg.sender, _slashAmount, cost, _reason);
    }

    // ========================================== Discovery =========================================

    /**
     * @notice Get all active relays
     * @return Array of active relay addresses
     */
    function getActiveRelays() external view returns (address[] memory) {
        return activeRelays;
    }

    /**
     * @notice Get number of active relays
     * @return Count of active relays
     */
    function getActiveRelayCount() external view returns (uint256) {
        return activeRelays.length;
    }

    /**
     * @notice Get relay info by address
     * @param _relay Relay address
     * @return Relay information struct
     */
    function getRelayInfo(address _relay) external view returns (ParticipantInfo memory) {
        ParticipantInfo memory participant = participants[_relay];
        // Only return if it's actually a relay (has endpoint)
        if (bytes(participant.endpoint).length == 0 && participant.registeredAt == 0) {
            revert RelayNotRegistered();
        }
        return participant;
    }

    /**
     * @notice Check if an address is a registered active relay
     * @param _relay Address to check
     * @return True if active relay
     */
    function isActiveRelay(address _relay) external view returns (bool) {
        ParticipantInfo memory participant = participants[_relay];
        return participant.status == ParticipantStatus.Active && bytes(participant.endpoint).length > 0;
    }

    // ========================================== User Management ==========================================

    /**
     * @notice Register user for encrypted data exchange
     * @param _pubkey Encryption public key (bytes, JSON format: "x.y" or JWK)
     * @param _epub Ephemeral encryption public key (bytes, JSON format: "x.y" or JWK)
     * @dev Keys stored as bytes, interpreted as extended JSON off-chain
     *      Format follows GunDB SEA standard: "x.y" coordinates or JWK
     */
    function registerUser(
        bytes calldata _pubkey,
        bytes calldata _epub
    ) external {
        if (_pubkey.length == 0) revert InvalidPubkey();
        if (_epub.length == 0) revert InvalidEpub();
        
        // If user already exists, preserve stake and slashed amounts
        // Check if already registered as relay (has endpoint) - users can't have endpoint
        ParticipantInfo memory existing = participants[msg.sender];
        if (bytes(existing.endpoint).length > 0) revert RelayAlreadyRegistered(); // Already a relay
        
        bool isNewUser = existing.registeredAt == 0;
        
        participants[msg.sender] = ParticipantInfo({
            owner: msg.sender,
            endpoint: "", // Users don't have endpoint
            pubkey: _pubkey,
            epub: _epub,
            stakedAmount: isNewUser ? 0 : existing.stakedAmount,
            registeredAt: isNewUser ? block.timestamp : existing.registeredAt,
            updatedAt: block.timestamp,
            unstakeRequestedAt: 0, // Users don't unstake
            status: ParticipantStatus.Active,
            totalSlashed: isNewUser ? 0 : existing.totalSlashed,
            griefingRatio: (isNewUser || existing.griefingRatio == 0) ? defaultGriefingRatio : existing.griefingRatio
        });
        
        // Add to active participants list if new
        if (isNewUser) {
            activeParticipantIndex[msg.sender] = activeParticipants.length;
            activeParticipants.push(msg.sender);
        }
        
        emit UserRegistered(msg.sender, _pubkey, _epub);
    }

    /**
     * @notice Update user encryption keys
     * @param _pubkey New encryption public key (empty to keep current)
     * @param _epub New ephemeral encryption public key (empty to keep current)
     */
    function updateUserKeys(
        bytes calldata _pubkey,
        bytes calldata _epub
    ) external {
        ParticipantInfo storage participant = participants[msg.sender];
        if (participant.registeredAt == 0) revert UserNotRegistered();
        if (bytes(participant.endpoint).length > 0) revert RelayNotActive(); // Must be user (no endpoint)
        
        if (_pubkey.length > 0) {
            participant.pubkey = _pubkey;
        }
        if (_epub.length > 0) {
            participant.epub = _epub;
        }
        
        participant.updatedAt = block.timestamp;
        
        emit UserKeysUpdated(msg.sender, participant.pubkey, participant.epub);
    }

    /**
     * @notice Deposit stake for user (optional, for griefing protection)
     * @param _amount Amount of USDC to stake
     * @param _griefingRatio Custom griefing ratio (0 to use default)
     */
    function depositUserStake(uint256 _amount, uint256 _griefingRatio) external nonReentrant {
        if (_amount == 0) revert InvalidAmount();
        ParticipantInfo storage participant = participants[msg.sender];
        if (participant.registeredAt == 0) revert UserNotRegistered();
        if (bytes(participant.endpoint).length > 0) revert UserNotRegistered(); // Must be user (no endpoint)

        stakingToken.safeTransferFrom(msg.sender, address(this), _amount);
        participant.stakedAmount += _amount;

        // Update griefing ratio if provided
        if (_griefingRatio > 0) {
            participant.griefingRatio = _griefingRatio;
        } else if (participant.griefingRatio == 0) {
            participant.griefingRatio = defaultGriefingRatio;
        }

        participant.updatedAt = block.timestamp;
        emit UserStakeDeposited(msg.sender, _amount, participant.stakedAmount);
    }

    /**
     * @notice Withdraw user stake
     * @param _amount Amount to withdraw
     */
    function withdrawUserStake(uint256 _amount) external nonReentrant {
        if (_amount == 0) revert InvalidAmount();
        ParticipantInfo storage participant = participants[msg.sender];
        if (participant.registeredAt == 0) revert UserNotRegistered();
        if (bytes(participant.endpoint).length > 0) revert UserNotRegistered(); // Must be user (no endpoint)
        if (participant.stakedAmount < _amount) revert InvalidAmount();

        participant.stakedAmount -= _amount;
        stakingToken.safeTransfer(msg.sender, _amount);

        participant.updatedAt = block.timestamp;
        emit UserStakeWithdrawn(msg.sender, _amount, participant.stakedAmount);
    }

    /**
     * @notice Grief a user (similar to relay griefing)
     * @param _user User address to grief
     * @param _slashAmount Amount to slash from user stake
     * @param _reason Reason for griefing
     * @dev Reporter pays griefing cost proportional to slash amount
     */
    function griefUser(
        address _user,
        uint256 _slashAmount,
        string calldata _reason
    ) external nonReentrant {
        ParticipantInfo storage participant = participants[_user];
        if (participant.registeredAt == 0) revert UserNotRegistered();
        if (bytes(participant.endpoint).length > 0) revert UserNotRegistered(); // Must be user (no endpoint)
        if (participant.status != ParticipantStatus.Active) revert UserNotRegistered();
        
        // Validate slash amount
        if (_slashAmount == 0) revert InvalidSlashAmount();
        if (_slashAmount > participant.stakedAmount) revert InvalidSlashAmount();

        // Calculate cost: griefingRatio basis points of slashAmount
        uint256 cost = (_slashAmount * participant.griefingRatio) / 10000;
        
        // Transfer cost from reporter
        stakingToken.safeTransferFrom(msg.sender, address(this), cost);

        // Slash user stake
        participant.stakedAmount -= _slashAmount;
        participant.totalSlashed += _slashAmount;

        // Generate report ID
        totalReports++;
        bytes32 reportId = keccak256(abi.encodePacked(
            _user,
            msg.sender,
            block.timestamp,
            totalReports
        ));

        slashReports[reportId] = SlashReport({
            reportId: reportId,
            reporter: msg.sender,
            relay: _user, // Reusing relay field for user address
            dealId: bytes32(0),
            reason: _reason,
            amount: _slashAmount,
            cost: cost,
            timestamp: block.timestamp
        });

        // Transfer slashed amount and cost to treasury (or burn address)
        // Note: USDC doesn't support burn(), so we use a dedicated burn address
        address recipient = treasury != address(0) ? treasury : BURN_ADDRESS;
        
        stakingToken.safeTransfer(recipient, _slashAmount);
        stakingToken.safeTransfer(recipient, cost);

        emit UserSlashed(reportId, _user, msg.sender, _slashAmount, cost, _reason);
    }

    /**
     * @notice Get user info by address
     * @param _user User address
     * @return User information struct
     */
    function getUserInfo(address _user) external view returns (ParticipantInfo memory) {
        ParticipantInfo memory participant = participants[_user];
        // Only return if it's actually a user (no endpoint)
        if (bytes(participant.endpoint).length > 0) {
            revert UserNotRegistered(); // This is a relay, not a user
        }
        return participant;
    }

    /**
     * @notice Get all active users (participants without endpoint)
     * @return Array of active user addresses
     */
    function getActiveUsers() external view returns (address[] memory) {
        uint256 userCount = 0;
        // First pass: count users
        for (uint256 i = 0; i < activeParticipants.length; i++) {
            ParticipantInfo memory p = participants[activeParticipants[i]];
            if (bytes(p.endpoint).length == 0 && p.status == ParticipantStatus.Active) {
                userCount++;
            }
        }
        
        // Second pass: collect user addresses
        address[] memory users = new address[](userCount);
        uint256 index = 0;
        for (uint256 i = 0; i < activeParticipants.length; i++) {
            ParticipantInfo memory p = participants[activeParticipants[i]];
            if (bytes(p.endpoint).length == 0 && p.status == ParticipantStatus.Active) {
                users[index] = activeParticipants[i];
                index++;
            }
        }
        return users;
    }

    /**
     * @notice Get number of active users
     * @return Count of active users
     */
    function getActiveUserCount() external view returns (uint256) {
        uint256 count = 0;
        for (uint256 i = 0; i < activeParticipants.length; i++) {
            ParticipantInfo memory p = participants[activeParticipants[i]];
            if (bytes(p.endpoint).length == 0 && p.status == ParticipantStatus.Active) {
                count++;
            }
        }
        return count;
    }


    // ========================================== Admin =============================================

    /**
     * @notice Set minimum stake requirement
     * @param _minStake New minimum stake (6 decimals for USDC)
     */
    function setMinStake(uint256 _minStake) external onlyOwner {
        minStake = _minStake;
    }

    /**
     * @notice Set unstaking delay
     * @param _delay New delay in seconds
     */
    function setUnstakingDelay(uint256 _delay) external onlyOwner {
        unstakingDelay = _delay;
    }

    /**
     * @notice Set griefing ratios
     * @param _defaultRatio Default griefing ratio (basis points)
     * @param _stakedRatio Griefing ratio for staked clients (basis points)
     */
    function setGriefingRatios(uint256 _defaultRatio, uint256 _stakedRatio) external onlyOwner {
        defaultGriefingRatio = _defaultRatio;
        stakedClientGriefingRatio = _stakedRatio;
    }

    /**
     * @notice Set treasury address (zero address = burn)
     * @param _treasury New treasury address
     */
    function setTreasury(address _treasury) external onlyOwner {
        treasury = _treasury;
    }

    /**
     * @notice Set TokenRegistry address for future multi-token support
     * @param _tokenRegistry Address of TokenRegistry contract (can be zero to disable)
     * @dev This allows future integration with TokenRegistry for multi-token support
     *      Current implementation still uses immutable stakingToken, but this field
     *      can be used by upgraded contracts or new versions
     */
    function setTokenRegistry(address _tokenRegistry) external onlyOwner {
        tokenRegistry = _tokenRegistry;
        // Future: emit event when TokenRegistry integration is implemented
    }

    /**
     * @notice Pause the contract
     */
    function pause() external onlyOwner {
        _pause();
    }

    /**
     * @notice Unpause the contract
     */
    function unpause() external onlyOwner {
        _unpause();
    }

    /**
     * @notice Emergency withdraw stuck tokens
     * @param _token Token address
     * @param _amount Amount to withdraw
     */
    function emergencyWithdraw(address _token, uint256 _amount) external onlyOwner {
        IERC20(_token).safeTransfer(owner(), _amount);
    }

    // ======================================== Internal ============================================

    /**
     * @notice Remove relay from active list
     */
    function _removeFromActiveRelays(address _relay) internal {
        uint256 index = activeRelayIndex[_relay];
        uint256 lastIndex = activeRelays.length - 1;

        if (index != lastIndex) {
            address lastRelay = activeRelays[lastIndex];
            activeRelays[index] = lastRelay;
            activeRelayIndex[lastRelay] = index;
        }

        activeRelays.pop();
        delete activeRelayIndex[_relay];
    }
}

contracts/registry/TokenRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/**
 * @title TokenRegistry
 * @notice Registry for supported ERC20 tokens in the Shogun protocol
 * @dev Allows adding new tokens in the future without redeploying core contracts
 * 
 * This registry enables:
 * - Multi-token support for staking and payments
 * - Per-token configuration (minStake, decimals, etc.)
 * - Token enable/disable functionality
 * - Future extensibility without contract upgrades
 */
contract TokenRegistry is Ownable, Pausable {
    // =========================================== Types ===========================================

    /// @notice Token configuration
    struct TokenConfig {
        address tokenAddress;      // ERC20 token address
        uint256 minStake;          // Minimum stake for this token
        uint8 decimals;            // Token decimals
        bool enabled;              // Whether token is enabled
        uint256 addedAt;           // When token was added
    }

    // =========================================== State ===========================================

    /// @notice Supported tokens by address
    mapping(address => TokenConfig) public tokens;

    /// @notice List of all registered token addresses
    address[] public tokenList;

    /// @notice Index in tokenList array
    mapping(address => uint256) private tokenIndex;

    /// @notice Default token (for backward compatibility)
    address public defaultToken;

    /// @notice Total registered tokens
    uint256 public totalTokens;

    // =========================================== Events ==========================================

    event TokenAdded(
        address indexed token,
        uint256 minStake,
        uint8 decimals,
        bool isDefault
    );

    event TokenUpdated(
        address indexed token,
        uint256 newMinStake,
        bool enabled
    );

    event TokenRemoved(
        address indexed token
    );

    event DefaultTokenChanged(
        address indexed oldToken,
        address indexed newToken
    );

    // =========================================== Errors ==========================================

    error TokenNotFound();
    error TokenAlreadyRegistered();
    error InvalidTokenAddress();
    error InvalidMinStake();
    error CannotRemoveDefaultToken();
    error TokenDisabled();

    // ========================================= Constructor ========================================

    constructor(address _defaultToken, uint256 _defaultMinStake, uint8 _defaultDecimals) Ownable(msg.sender) {
        if (_defaultToken == address(0)) revert InvalidTokenAddress();
        
        defaultToken = _defaultToken;
        tokens[_defaultToken] = TokenConfig({
            tokenAddress: _defaultToken,
            minStake: _defaultMinStake,
            decimals: _defaultDecimals,
            enabled: true,
            addedAt: block.timestamp
        });
        
        tokenList.push(_defaultToken);
        tokenIndex[_defaultToken] = 0;
        totalTokens = 1;

        emit TokenAdded(_defaultToken, _defaultMinStake, _defaultDecimals, true);
    }

    // =========================================== Functions ========================================

    /**
     * @notice Add a new supported token
     * @param _token Token address
     * @param _minStake Minimum stake for this token
     * @param _decimals Token decimals
     * @param _setAsDefault Whether to set as new default token
     */
    function addToken(
        address _token,
        uint256 _minStake,
        uint8 _decimals,
        bool _setAsDefault
    ) external onlyOwner {
        if (_token == address(0)) revert InvalidTokenAddress();
        if (tokens[_token].addedAt > 0) revert TokenAlreadyRegistered();
        if (_minStake == 0) revert InvalidMinStake();

        tokens[_token] = TokenConfig({
            tokenAddress: _token,
            minStake: _minStake,
            decimals: _decimals,
            enabled: true,
            addedAt: block.timestamp
        });

        tokenIndex[_token] = tokenList.length;
        tokenList.push(_token);
        totalTokens++;

        if (_setAsDefault) {
            address oldDefault = defaultToken;
            defaultToken = _token;
            emit DefaultTokenChanged(oldDefault, _token);
        }

        emit TokenAdded(_token, _minStake, _decimals, _setAsDefault);
    }

    /**
     * @notice Update token configuration
     * @param _token Token address
     * @param _newMinStake New minimum stake (0 to keep current)
     * @param _enabled Whether token is enabled
     */
    function updateToken(
        address _token,
        uint256 _newMinStake,
        bool _enabled
    ) external onlyOwner {
        if (tokens[_token].addedAt == 0) revert TokenNotFound();
        if (_newMinStake > 0 && _newMinStake != tokens[_token].minStake) {
            if (_newMinStake == 0) revert InvalidMinStake();
            tokens[_token].minStake = _newMinStake;
        }
        
        tokens[_token].enabled = _enabled;

        emit TokenUpdated(_token, tokens[_token].minStake, _enabled);
    }

    /**
     * @notice Remove a token (cannot remove default token)
     * @param _token Token address
     */
    function removeToken(address _token) external onlyOwner {
        if (tokens[_token].addedAt == 0) revert TokenNotFound();
        if (_token == defaultToken) revert CannotRemoveDefaultToken();

        // Remove from list
        uint256 index = tokenIndex[_token];
        uint256 lastIndex = tokenList.length - 1;

        if (index != lastIndex) {
            address lastToken = tokenList[lastIndex];
            tokenList[index] = lastToken;
            tokenIndex[lastToken] = index;
        }

        tokenList.pop();
        delete tokenIndex[_token];
        delete tokens[_token];
        totalTokens--;

        emit TokenRemoved(_token);
    }

    /**
     * @notice Set a new default token
     * @param _token New default token address
     */
    function setDefaultToken(address _token) external onlyOwner {
        if (tokens[_token].addedAt == 0) revert TokenNotFound();
        if (!tokens[_token].enabled) revert TokenDisabled();

        address oldDefault = defaultToken;
        defaultToken = _token;

        emit DefaultTokenChanged(oldDefault, _token);
    }

    // =========================================== View Functions ====================================

    /**
     * @notice Check if a token is supported and enabled
     * @param _token Token address
     * @return True if token is supported and enabled
     */
    function isTokenSupported(address _token) external view returns (bool) {
        return tokens[_token].addedAt > 0 && tokens[_token].enabled;
    }

    /**
     * @notice Get token configuration
     * @param _token Token address
     * @return Token configuration
     */
    function getTokenConfig(address _token) external view returns (TokenConfig memory) {
        if (tokens[_token].addedAt == 0) revert TokenNotFound();
        return tokens[_token];
    }

    /**
     * @notice Get minimum stake for a token
     * @param _token Token address
     * @return Minimum stake amount
     */
    function getMinStake(address _token) external view returns (uint256) {
        if (tokens[_token].addedAt == 0) revert TokenNotFound();
        return tokens[_token].minStake;
    }

    /**
     * @notice Get all supported tokens
     * @return Array of token addresses
     */
    function getAllTokens() external view returns (address[] memory) {
        return tokenList;
    }

    /**
     * @notice Get enabled tokens only
     * @return Array of enabled token addresses
     */
    function getEnabledTokens() external view returns (address[] memory) {
        uint256 enabledCount = 0;
        
        // Count enabled tokens
        for (uint256 i = 0; i < tokenList.length; i++) {
            if (tokens[tokenList[i]].enabled) {
                enabledCount++;
            }
        }

        // Collect enabled tokens
        address[] memory enabled = new address[](enabledCount);
        uint256 index = 0;
        for (uint256 i = 0; i < tokenList.length; i++) {
            if (tokens[tokenList[i]].enabled) {
                enabled[index] = tokenList[i];
                index++;
            }
        }

        return enabled;
    }

    // =========================================== Admin =============================================

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }
}

contracts/stealth/IPaymentForwarderHookR.content:
// SPDX-License-Identifier: MIT

pragma solidity ^0.8.24;

/// @dev Interface that post-withdraw hooks must implement to interop with Umbra
interface IPaymentForwarderHookReceiver {
  /**
   * @notice Method called after a user completes an Umbra token withdrawal
   * @param _amount The amount of the token withdrawn _after_ subtracting the sponsor fee
   * @param _stealthAddr The stealth address whose token balance was withdrawn
   * @param _acceptor Address where withdrawn funds were sent; can be this contract
   * @param _tokenAddr Address of the ERC20 token that was withdrawn
   * @param _sponsor Address which was compensated for submitting the withdrawal tx
   * @param _sponsorFee Amount of the token that was paid to the sponsor
   * @param _data Arbitrary data passed to this hook by the withdrawer
   */
  function tokensWithdrawn(
    uint256 _amount,
    address _stealthAddr,
    address _acceptor,
    address _tokenAddr,
    address _sponsor,
    uint256 _sponsorFee,
    bytes memory _data
  ) external;
}

contracts/stealth/PaymentForwarder.sol.content:
// SPDX-License-Identifier: MIT

pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "./IPaymentForwarderHookReceiver.sol";

contract PayamentForwarder is Ownable {
  // =========================================== Events ============================================

  /// @notice Emitted when a payment is sent
  event Announcement(
    address indexed receiver, // stealth address
    uint256 amount, // funds
    address indexed token, // token address or ETH placeholder
    bytes32 pkx, // ephemeral public key x coordinate
    bytes32 ciphertext // encrypted entropy and payload extension
  );

  /// @notice Emitted when a token is withdrawn
  event TokenWithdrawal(
    address indexed receiver, // stealth address
    address indexed acceptor, // destination of funds
    uint256 amount, // funds
    address indexed token // token address
  );

  // ======================================= State variables =======================================

  /// @dev Placeholder address used to identify transfer of native ETH
  address internal constant ETH_TOKEN_PLACHOLDER = 0xEeeeeEeeeEeEeeEeEeEeeEEEeeeeEeeeeeeeEEeE;

  /// @notice An ETH amount that must be sent alongside each payment; used as an anti-spam measure
  uint256 public toll;

  /// @notice A privileged address, set by the admin, that can sweep all collected ETH tolls
  address public tollCollector;

  /// @notice The address where ETH funds are sent when collected by the tollCollector
  address payable public tollReceiver;

  /// @notice Token payments pending withdrawal; stealth address => token address => amount
  mapping(address => mapping(address => uint256)) public tokenPayments;

  // ======================================= Setup & Admin ========================================

  /**
   * @param _toll Amount of ETH required per send
   * @param _tollCollector Address that can sweep collected funds
   * @param _tollReceiver Address that receives collected funds
   */
  constructor(
    uint256 _toll,
    address _tollCollector,
    address payable _tollReceiver
  ) Ownable(msg.sender) {
    toll = _toll;
    tollCollector = _tollCollector;
    tollReceiver = _tollReceiver;
  }

  /**
   * @notice Admin only function to update the toll
   * @param _newToll New ETH toll in wei
   */
  function setToll(uint256 _newToll) external onlyOwner {
    toll = _newToll;
  }

  /**
   * @notice Admin only function to update the toll collector
   * @param _newTollCollector New address which has fund sweeping privileges
   */
  function setTollCollector(address _newTollCollector) external onlyOwner {
    tollCollector = _newTollCollector;
  }

  /**
   * @notice Admin only function to update the toll receiver
   * @param _newTollReceiver New address which receives collected funds
   */
  function setTollReceiver(address payable _newTollReceiver) external onlyOwner {
    tollReceiver = _newTollReceiver;
  }

  /**
   * @notice Function only the toll collector can call to sweep funds to the toll receiver
   */
  function collectTolls() external {
    require(msg.sender == tollCollector, "PaymentForwarder: Not toll collector");
    tollReceiver.transfer(address(this).balance);
  }

  // ======================================= Send =================================================

  /**
   * @notice Send and announce ETH payment to a stealth address
   * @param _receiver Stealth address receiving the payment
   * @param _tollCommitment Exact toll the sender is paying; should equal contract toll;
   * the committment is used to prevent frontrunning attacks by the owner;
   * see https://github.com/ScopeLift/umbra-protocol/issues/54 for more information
   * @param _pkx X-coordinate of the ephemeral public key used to encrypt the payload
   * @param _ciphertext Encrypted entropy (used to generated the stealth address) and payload extension
   */
  function sendEth(
    address payable _receiver,
    uint256 _tollCommitment,
    bytes32 _pkx, // ephemeral public key x coordinate
    bytes32 _ciphertext
  ) external payable {
    require(_tollCommitment == toll, "PaymentForwarder: Invalid or outdated toll commitment");

    // also protects from underflow
    require(msg.value > toll, "PaymentForwarder: Must pay more than the toll");

    uint256 amount = msg.value - toll;
    emit Announcement(_receiver, amount, ETH_TOKEN_PLACHOLDER, _pkx, _ciphertext);

    _receiver.transfer(amount);
  }

  /**
   * @notice Send and announce an ERC20 payment to a stealth address
   * @param _receiver Stealth address receiving the payment
   * @param _tokenAddr Address of the ERC20 token being sent
   * @param _amount Amount of the token to send, in its own base units
   * @param _pkx X-coordinate of the ephemeral public key used to encrypt the payload
   * @param _ciphertext Encrypted entropy (used to generated the stealth address) and payload extension
   */
  function sendToken(
    address _receiver,
    address _tokenAddr,
    uint256 _amount,
    bytes32 _pkx, // ephemeral public key x coordinate
    bytes32 _ciphertext
  ) external payable {
    require(msg.value == toll, "PaymentForwarder: Must pay the exact toll");
    require(tokenPayments[_receiver][_tokenAddr] == 0, "PaymentForwarder: Cannot send more tokens to stealth address");

    tokenPayments[_receiver][_tokenAddr] = _amount;
    emit Announcement(_receiver, _amount, _tokenAddr, _pkx, _ciphertext);

    SafeERC20.safeTransferFrom(IERC20(_tokenAddr), msg.sender, address(this), _amount);
  }

  // ======================================= Withdraw =============================================

  /**
   * @notice Withdraw an ERC20 token payment sent to a stealth address
   * @dev This method must be directly called by the stealth address
   * @param _acceptor Address where withdrawn funds should be sent
   * @param _tokenAddr Address of the ERC20 token being withdrawn
   */
  function withdrawToken(address _acceptor, address _tokenAddr) external {
    _withdrawTokenInternal(msg.sender, _acceptor, _tokenAddr, address(0), 0, IPaymentForwarderHookReceiver(address(0)), "");
  }

  /**
   * @notice Withdraw an ERC20 token payment sent to a stealth address
   * @dev This method must be directly called by the stealth address
   * @param _acceptor Address where withdrawn funds should be sent
   * @param _tokenAddr Address of the ERC20 token being withdrawn
   * @param _hook Contract that will be called after the token withdrawal has completed
   * @param _data Arbitrary data that will be passed to the post-withdraw hook contract
   */
  function withdrawTokenAndCall(
    address _acceptor,
    address _tokenAddr,
    IPaymentForwarderHookReceiver _hook,
    bytes memory _data
  ) external {
    _withdrawTokenInternal(msg.sender, _acceptor, _tokenAddr, address(0), 0, _hook, _data);
  }

  /**
   * @notice Withdraw an ERC20 token payment on behalf of a stealth address via signed authorization
   * @param _stealthAddr The stealth address whose token balance will be withdrawn
   * @param _acceptor Address where withdrawn funds should be sent
   * @param _tokenAddr Address of the ERC20 token being withdrawn
   * @param _sponsor Address which is compensated for submitting the withdrawal tx
   * @param _sponsorFee Amount of the token to pay to the sponsor
   * @param _v ECDSA signature component: Parity of the `y` coordinate of point `R`
   * @param _r ECDSA signature component: x-coordinate of `R`
   * @param _s ECDSA signature component: `s` value of the signature
   */
  function withdrawTokenOnBehalf(
    address _stealthAddr,
    address _acceptor,
    address _tokenAddr,
    address _sponsor,
    uint256 _sponsorFee,
    uint8 _v,
    bytes32 _r,
    bytes32 _s
  ) external {
    _validateWithdrawSignature(
      _stealthAddr,
      _acceptor,
      _tokenAddr,
      _sponsor,
      _sponsorFee,
      IPaymentForwarderHookReceiver(address(0)),
      "",
      _v,
      _r,
      _s
    );
    _withdrawTokenInternal(_stealthAddr, _acceptor, _tokenAddr, _sponsor, _sponsorFee, IPaymentForwarderHookReceiver(address(0)), "");
  }

  /**
   * @notice Withdraw an ERC20 token payment on behalf of a stealth address via signed authorization
   * @param _stealthAddr The stealth address whose token balance will be withdrawn
   * @param _acceptor Address where withdrawn funds should be sent
   * @param _tokenAddr Address of the ERC20 token being withdrawn
   * @param _sponsor Address which is compensated for submitting the withdrawal tx
   * @param _sponsorFee Amount of the token to pay to the sponsor
   * @param _hook Contract that will be called after the token withdrawal has completed
   * @param _data Arbitrary data that will be passed to the post-withdraw hook contract
   * @param _v ECDSA signature component: Parity of the `y` coordinate of point `R`
   * @param _r ECDSA signature component: x-coordinate of `R`
   * @param _s ECDSA signature component: `s` value of the signature
   */
  function withdrawTokenAndCallOnBehalf(
    address _stealthAddr,
    address _acceptor,
    address _tokenAddr,
    address _sponsor,
    uint256 _sponsorFee,
    IPaymentForwarderHookReceiver _hook,
    bytes memory _data,
    uint8 _v,
    bytes32 _r,
    bytes32 _s
  ) external {
    _validateWithdrawSignature(_stealthAddr, _acceptor, _tokenAddr, _sponsor, _sponsorFee, _hook, _data, _v, _r, _s);
    _withdrawTokenInternal(_stealthAddr, _acceptor, _tokenAddr, _sponsor, _sponsorFee, _hook, _data);
  }

  /**
   * @notice Low level withdrawal function that should only be called after safety checks
   * @param _stealthAddr The stealth address whose token balance will be withdrawn
   * @param _acceptor Address where withdrawn funds should be sent
   * @param _tokenAddr Address of the ERC20 token being withdrawn
   * @param _sponsor Address which is compensated for submitting the withdrawal tx
   * @param _sponsorFee Amount of the token to pay to the sponsor
   * @param _hook Contract that will be called after the token withdrawal has completed
   * @param _data Arbitrary data that will be passed to the post-withdraw hook contract
   */
  function _withdrawTokenInternal(
    address _stealthAddr,
    address _acceptor,
    address _tokenAddr,
    address _sponsor,
    uint256 _sponsorFee,
    IPaymentForwarderHookReceiver _hook,
    bytes memory _data
  ) internal {
    uint256 _amount = tokenPayments[_stealthAddr][_tokenAddr];

    // also protects from underflow
    require(_amount > _sponsorFee, "PaymentForwarder: No balance to withdraw or fee exceeds balance");

    uint256 _withdrawalAmount = _amount - _sponsorFee;
    delete tokenPayments[_stealthAddr][_tokenAddr];
    emit TokenWithdrawal(_stealthAddr, _acceptor, _withdrawalAmount, _tokenAddr);

    SafeERC20.safeTransfer(IERC20(_tokenAddr), _acceptor, _withdrawalAmount);

    if (_sponsorFee > 0) {
      SafeERC20.safeTransfer(IERC20(_tokenAddr), _sponsor, _sponsorFee);
    }

    if (address(_hook) != address(0)) {
      _hook.tokensWithdrawn(_withdrawalAmount, _stealthAddr, _acceptor, _tokenAddr, _sponsor, _sponsorFee, _data);
    }
  }

  /**
   * @notice Internal method which recovers address from signature of the parameters and throws if not _stealthAddr
   * @param _stealthAddr The stealth address whose token balance will be withdrawn
   * @param _acceptor Address where withdrawn funds should be sent
   * @param _tokenAddr Address of the ERC20 token being withdrawn
   * @param _sponsor Address which is compensated for submitting the withdrawal tx
   * @param _sponsorFee Amount of the token to pay to the sponsor
   * @param _hook Contract that will be called after the token withdrawal has completed
   * @param _data Arbitrary data that will be passed to the post-withdraw hook contract
   * @param _v ECDSA signature component: Parity of the `y` coordinate of point `R`
   * @param _r ECDSA signature component: x-coordinate of `R`
   * @param _s ECDSA signature component: `s` value of the signature
   */
  function _validateWithdrawSignature(
    address _stealthAddr,
    address _acceptor,
    address _tokenAddr,
    address _sponsor,
    uint256 _sponsorFee,
    IPaymentForwarderHookReceiver _hook,
    bytes memory _data,
    uint8 _v,
    bytes32 _r,
    bytes32 _s
  ) internal view {
    uint256 _chainId;
    assembly {
      _chainId := chainid()
    }

    bytes32 _digest =
      keccak256(
        abi.encodePacked(
          "\x19Ethereum Signed Message:\n32",
          keccak256(
            abi.encode(_chainId, address(this), _acceptor, _tokenAddr, _sponsor, _sponsorFee, address(_hook), _data)
          )
        )
      );

    address _recoveredAddress = ecrecover(_digest, _v, _r, _s);
    require(_recoveredAddress != address(0) && _recoveredAddress == _stealthAddr, "PaymentForwarder: Invalid Signature");
  }
}

